select sum(l_extendedprice * (1 - l_discount)) as revenue from lineitem, part where ( p_partkey = l_partkey and p_brand = 'Brand#35' and p_container in ('MED BOX', 'JUMBO PACK', 'WRAP JAR', 'LG BAG', 'SM PKG', 'JUMBO CASE', 'LG PACK', 'WRAP PACK') and l_quantity >= 3 and l_quantity <= 14 and p_size between 1 and 8 and l_shipmode in ('AIR', 'AIR REG') and l_shipinstruct = 'DELIVER IN PERSON' ) or ( p_partkey = l_partkey and p_brand = 'Brand#24' and p_container in ('LG BOX', 'WRAP BOX', 'JUMBO CASE', 'SM JAR', 'LG BAG', 'MED CASE', 'SM BOX', 'WRAP CASE') and l_quantity >= 14 and l_quantity <= 23 and p_size between 1 and 13 and l_shipmode in ('AIR', 'AIR REG') and l_shipinstruct = 'DELIVER IN PERSON' ) or ( p_partkey = l_partkey and p_brand = 'Brand#42' and p_container in ('SM DRUM', 'JUMBO BAG', 'SM CAN', 'WRAP PACK', 'LG JAR', 'LG DRUM', 'SM CASE', 'SM BOX') and l_quantity >= 27 and l_quantity <= 36 and p_size between 1 and 20 and l_shipmode in ('AIR', 'AIR REG') and l_shipinstruct = 'DELIVER IN PERSON' );
select l_shipmode, sum(case when o_orderpriority = '1-URGENT' or o_orderpriority = '2-HIGH' then 1 else 0 end) as high_line_count, sum(case when o_orderpriority <> '1-URGENT' and o_orderpriority <> '2-HIGH' then 1 else 0 end) as low_line_count from orders, lineitem where o_orderkey = l_orderkey and l_shipmode in ('AIR', 'TRUCK', 'REG AIR', 'RAIL') and l_commitdate < l_receiptdate and l_shipdate < l_commitdate and l_receiptdate >= date '1995-04-16' and l_receiptdate < DATE '1995-04-16' + INTERVAL 5 YEAR group by l_shipmode order by l_shipmode;
select supp_nation, cust_nation, l_year, sum(volume) as revenue from ( select n1.n_name as supp_nation, n2.n_name as cust_nation, extract(year from l_shipdate) as l_year, l_extendedprice * (1 - l_discount) as volume from supplier, lineitem, orders, customer, nation n1, nation n2 where s_suppkey = l_suppkey and o_orderkey = l_orderkey and c_custkey = o_custkey and s_nationkey = n1.n_nationkey and c_nationkey = n2.n_nationkey and ((n1.n_name = 'ROMANIA' and n2.n_name = 'KENYA') or (n1.n_name = 'ROMANIA' and n2.n_name = 'INDONESIA')) and l_shipdate between date '1995-01-01' and date '1998-12-31' ) as shipping group by supp_nation, cust_nation, l_year order by supp_nation, cust_nation, l_year;
select s_acctbal, s_name, n_name, p_partkey, p_mfgr, s_address, s_phone, s_comment from part, supplier, partsupp, nation, region where p_partkey = ps_partkey and s_suppkey = ps_suppkey and p_size >= 9 and p_size <= 18 and (p_type like '%STEEL') and s_nationkey = n_nationkey and n_regionkey = r_regionkey and (r_name = 'MIDDLE EAST') and ps_supplycost = ( select min(ps_supplycost) from partsupp, supplier, nation, region where p_partkey = ps_partkey and s_suppkey = ps_suppkey and s_nationkey = n_nationkey and n_regionkey = r_regionkey and (r_name = 'MIDDLE EAST') ) order by s_acctbal desc, n_name, s_name, p_partkey LIMIT 100;
select p_brand, p_type, p_size, count(distinct ps_suppkey) as supplier_cnt from partsupp, part where p_partkey = ps_partkey and p_brand <> 'Brand#52' and p_type not like 'LARGE POLISHED%' and p_type not like 'ECONOMY ANODIZED%' and p_type not like 'SMALL BURNISHED%' and p_size in (30, 27, 2, 46, 42, 34, 26, 6) and ps_suppkey not in ( select s_suppkey from supplier where (s_comment like '%Customer%Problems%' or s_comment like '%Customer%Returns%' or s_comment like '%Customer%Complaints%') ) group by p_brand, p_type, p_size order by supplier_cnt desc, p_brand, p_type, p_size;
select o_orderpriority, count(*) as order_count from orders where o_orderdate >= date '1995-12-01' and o_orderdate < DATE '1995-12-01' + INTERVAL 34 MONTH and exists ( select * from lineitem where l_orderkey = o_orderkey and l_commitdate < l_receiptdate ) group by o_orderpriority order by o_orderpriority;
select c_count, count(*) as custdist from ( select c_custkey, count(o_orderkey) as c_count from customer left outer join orders on c_custkey = o_custkey and o_comment not like '%express%packages%' and o_comment not like '%unusual%packages%' and o_comment not like '%pending%packages%' group by c_custkey ) as c_orders group by c_count order by custdist desc, c_count desc;
select sum(l_extendedprice * l_discount) as revenue from lineitem where l_shipdate >= date '1996-06-26' and l_shipdate < DATE '1996-06-26' + INTERVAL 1 YEAR and l_discount between 0.06 - 0.02 and 0.06 + 0.02 and l_quantity < 21;
