select o_orderpriority, count(*) as order_count from orders where o_orderdate >= date '1995-12-01' and o_orderdate < DATE '1995-12-01' + INTERVAL 24 MONTH and exists ( select * from lineitem where l_orderkey = o_orderkey and l_commitdate < l_receiptdate ) group by o_orderpriority order by o_orderpriority;
select l_returnflag, l_linestatus, sum(l_quantity) as sum_qty, sum(l_extendedprice) as sum_base_price, sum(l_extendedprice * (1 - l_discount)) as sum_disc_price, sum(l_extendedprice * (1 - l_discount) * (1 + l_tax)) as sum_charge, avg(l_quantity) as avg_qty, avg(l_extendedprice) as avg_price, avg(l_discount) as avg_disc, count(*) as count_order from lineitem where l_shipdate <= DATE '1994-02-26' - INTERVAL 99 DAY group by l_returnflag, l_linestatus order by l_returnflag, l_linestatus;
select s_name, s_address from supplier, nation where s_suppkey in ( select ps_suppkey from partsupp where ps_partkey in ( select p_partkey from part where (p_name like '%blue%' or p_name like '%pink%' or p_name like '%grey%') ) and ps_availqty > ( select 0.5 * sum(l_quantity) from lineitem where l_partkey = ps_partkey and l_suppkey = ps_suppkey and l_shipdate >= date '1993-07-15' and l_shipdate < DATE '1993-07-15' + INTERVAL 2 YEAR ) ) and s_nationkey = n_nationkey and n_name = 'CHINA' order by s_name;
select 100.00 * sum(case when p_type like 'PROMO%' then l_extendedprice * (1 - l_discount) else 0 end) / sum(l_extendedprice * (1 - l_discount)) as promo_revenue from lineitem, part where l_partkey = p_partkey and l_shipdate >= date '1992-07-16' and l_shipdate < DATE '1992-07-16' + INTERVAL 23 MONTH;
select nation, o_year, sum(amount) as sum_profit from ( select n_name as nation, extract(year from o_orderdate) as o_year, l_extendedprice * (1 - l_discount) - ps_supplycost * l_quantity as amount from part, supplier, lineitem, partsupp, orders, nation where s_suppkey = l_suppkey and ps_suppkey = l_suppkey and ps_partkey = l_partkey and p_partkey = l_partkey and o_orderkey = l_orderkey and s_nationkey = n_nationkey and p_name like '%yellow%' ) as profit group by nation, o_year order by nation, o_year desc;
select 100.00 * sum(case when p_type like 'PROMO%' then l_extendedprice * (1 - l_discount) else 0 end) / sum(l_extendedprice * (1 - l_discount)) as promo_revenue from lineitem, part where l_partkey = p_partkey and l_shipdate >= date '1994-01-01' and l_shipdate < DATE '1994-01-01' + INTERVAL 8 MONTH;
select c_name, c_custkey, o_orderkey, o_orderdate, o_totalprice, sum(l_quantity) from customer, orders, lineitem where o_orderkey in ( select l_orderkey from lineitem group by l_orderkey having sum(l_quantity) > 190 ) and c_custkey = o_custkey and o_orderkey = l_orderkey group by c_name, c_custkey, o_orderkey, o_orderdate, o_totalprice order by o_totalprice desc, o_orderdate LIMIT 100;
select nation, o_year, sum(amount) as sum_profit from ( select n_name as nation, extract(year from o_orderdate) as o_year, l_extendedprice * (1 - l_discount) - ps_supplycost * l_quantity as amount from part, supplier, lineitem, partsupp, orders, nation where s_suppkey = l_suppkey and ps_suppkey = l_suppkey and ps_partkey = l_partkey and p_partkey = l_partkey and o_orderkey = l_orderkey and s_nationkey = n_nationkey and p_name like '%green%' ) as profit group by nation, o_year order by nation, o_year desc;
select s_acctbal, s_name, n_name, p_partkey, p_mfgr, s_address, s_phone, s_comment from part, supplier, partsupp, nation, region where p_partkey = ps_partkey and s_suppkey = ps_suppkey and p_size = 43 and (p_type like '%NICKEL') and s_nationkey = n_nationkey and n_regionkey = r_regionkey and (r_name = 'MIDDLE EAST') and ps_supplycost = ( select min(ps_supplycost) from partsupp, supplier, nation, region where p_partkey = ps_partkey and s_suppkey = ps_suppkey and s_nationkey = n_nationkey and n_regionkey = r_regionkey and (r_name = 'MIDDLE EAST') ) order by s_acctbal desc, n_name, s_name, p_partkey LIMIT 100;
select nation, o_year, sum(amount) as sum_profit from ( select n_name as nation, extract(year from o_orderdate) as o_year, l_extendedprice * (1 - l_discount) - ps_supplycost * l_quantity as amount from part, supplier, lineitem, partsupp, orders, nation where s_suppkey = l_suppkey and ps_suppkey = l_suppkey and ps_partkey = l_partkey and p_partkey = l_partkey and o_orderkey = l_orderkey and s_nationkey = n_nationkey and p_name like '%red%' ) as profit group by nation, o_year order by nation, o_year desc;
select supp_nation, cust_nation, l_year, sum(volume) as revenue from ( select n1.n_name as supp_nation, n2.n_name as cust_nation, extract(year from l_shipdate) as l_year, l_extendedprice * (1 - l_discount) as volume from supplier, lineitem, orders, customer, nation n1, nation n2 where s_suppkey = l_suppkey and o_orderkey = l_orderkey and c_custkey = o_custkey and s_nationkey = n1.n_nationkey and c_nationkey = n2.n_nationkey and ((n1.n_name = 'UNITED KINGDOM' and n2.n_name = 'MOROCCO') or (n1.n_name = 'UNITED STATES' and n2.n_name = 'MOROCCO')) and l_shipdate between date '1995-01-01' and date '1996-12-31' ) as shipping group by supp_nation, cust_nation, l_year order by supp_nation, cust_nation, l_year;
select ps_partkey, sum(ps_supplycost * ps_availqty) as value from partsupp, supplier, nation where ps_suppkey = s_suppkey and s_nationkey = n_nationkey and (n_name = 'ALGERIA' or n_name = 'SAUDI ARABIA' or n_name = 'MOZAMBIQUE') group by ps_partkey having sum(ps_supplycost * ps_availqty) > ( select sum(ps_supplycost * ps_availqty) * 0.0000019024 from partsupp, supplier, nation where ps_suppkey = s_suppkey and s_nationkey = n_nationkey and (n_name = 'ALGERIA' or n_name = 'SAUDI ARABIA' or n_name = 'MOZAMBIQUE') ) order by value desc;
select sum(l_extendedprice * (1 - l_discount)) as revenue from lineitem, part where ( p_partkey = l_partkey and p_brand = 'Brand#35' and p_container in ('LG PKG', 'SM CASE', 'WRAP PACK', 'JUMBO CASE', 'JUMBO JAR', 'MED PKG', 'WRAP CAN', 'SM CAN') and l_quantity >= 11 and l_quantity <= 20 and p_size between 1 and 4 and l_shipmode in ('AIR', 'AIR REG') and l_shipinstruct = 'DELIVER IN PERSON' ) or ( p_partkey = l_partkey and p_brand = 'Brand#24' and p_container in ('LG PACK', 'LG BAG', 'JUMBO PACK', 'JUMBO CAN', 'MED PKG', 'MED PACK', 'JUMBO PKG', 'LG JAR') and l_quantity >= 22 and l_quantity <= 31 and p_size between 1 and 8 and l_shipmode in ('AIR', 'AIR REG') and l_shipinstruct = 'DELIVER IN PERSON' ) or ( p_partkey = l_partkey and p_brand = 'Brand#42' and p_container in ('JUMBO DRUM', 'JUMBO PACK', 'MED DRUM', 'WRAP DRUM', 'LG CASE', 'WRAP CASE', 'SM JAR', 'LG BAG') and l_quantity >= 31 and l_quantity <= 39 and p_size between 1 and 22 and l_shipmode in ('AIR', 'AIR REG') and l_shipinstruct = 'DELIVER IN PERSON' );
select sum(l_extendedprice) / 7.0 as avg_yearly from lineitem, part where p_partkey = l_partkey and p_brand = 'Brand#24' and (p_container = 'LG PACK' or p_container = 'MED DRUM') and l_quantity < ( select 0.2 * avg(l_quantity) from lineitem where l_partkey = p_partkey );
select sum(l_extendedprice) / 7.0 as avg_yearly from lineitem, part where p_partkey = l_partkey and p_brand = 'Brand#24' and (p_container = 'WRAP DRUM' or p_container = 'JUMBO DRUM') and l_quantity < ( select 0.2 * avg(l_quantity) from lineitem where l_partkey = p_partkey );
select s_acctbal, s_name, n_name, p_partkey, p_mfgr, s_address, s_phone, s_comment from part, supplier, partsupp, nation, region where p_partkey = ps_partkey and s_suppkey = ps_suppkey and p_size = 7 and (p_type like '%STEEL') and s_nationkey = n_nationkey and n_regionkey = r_regionkey and (r_name = 'MIDDLE EAST' or r_name = 'ASIA') and ps_supplycost = ( select min(ps_supplycost) from partsupp, supplier, nation, region where p_partkey = ps_partkey and s_suppkey = ps_suppkey and s_nationkey = n_nationkey and n_regionkey = r_regionkey and (r_name = 'MIDDLE EAST' or r_name = 'ASIA') ) order by s_acctbal desc, n_name, s_name, p_partkey LIMIT 100;
select supp_nation, cust_nation, l_year, sum(volume) as revenue from ( select n1.n_name as supp_nation, n2.n_name as cust_nation, extract(year from l_shipdate) as l_year, l_extendedprice * (1 - l_discount) as volume from supplier, lineitem, orders, customer, nation n1, nation n2 where s_suppkey = l_suppkey and o_orderkey = l_orderkey and c_custkey = o_custkey and s_nationkey = n1.n_nationkey and c_nationkey = n2.n_nationkey and ((n1.n_name = 'JAPAN' and n2.n_name = 'BRAZIL') or (n1.n_name = 'BRAZIL' and n2.n_name = 'JAPAN')) and l_shipdate between date '1992-01-01' and date '1996-12-31' ) as shipping group by supp_nation, cust_nation, l_year order by supp_nation, cust_nation, l_year;
select l_returnflag, l_linestatus, sum(l_quantity) as sum_qty, sum(l_extendedprice) as sum_base_price, sum(l_extendedprice * (1 - l_discount)) as sum_disc_price, sum(l_extendedprice * (1 - l_discount) * (1 + l_tax)) as sum_charge, avg(l_quantity) as avg_qty, avg(l_extendedprice) as avg_price, avg(l_discount) as avg_disc, count(*) as count_order from lineitem where l_shipdate <= DATE '1994-02-10' - INTERVAL 99 DAY group by l_returnflag, l_linestatus order by l_returnflag, l_linestatus;
select c_name, c_custkey, o_orderkey, o_orderdate, o_totalprice, sum(l_quantity) from customer, orders, lineitem where o_orderkey in ( select l_orderkey from lineitem group by l_orderkey having sum(l_quantity) > 224 ) and c_custkey = o_custkey and o_orderkey = l_orderkey group by c_name, c_custkey, o_orderkey, o_orderdate, o_totalprice order by o_totalprice desc, o_orderdate LIMIT 100;
select l_shipmode, sum(case when o_orderpriority = '1-URGENT' or o_orderpriority = '2-HIGH' then 1 else 0 end) as high_line_count, sum(case when o_orderpriority <> '1-URGENT' and o_orderpriority <> '2-HIGH' then 1 else 0 end) as low_line_count from orders, lineitem where o_orderkey = l_orderkey and l_shipmode in ('MAIL', 'FOB', 'REG AIR', 'RAIL') and l_commitdate < l_receiptdate and l_shipdate < l_commitdate and l_receiptdate >= date '1996-03-15' and l_receiptdate < DATE '1996-03-15' + INTERVAL 5 YEAR group by l_shipmode order by l_shipmode;
select sum(l_extendedprice) / 7.0 as avg_yearly from lineitem, part where p_partkey = l_partkey and p_brand = 'Brand#24' and (p_container = 'LG CAN') and l_quantity < ( select 0.2 * avg(l_quantity) from lineitem where l_partkey = p_partkey );
select c_name, c_custkey, o_orderkey, o_orderdate, o_totalprice, sum(l_quantity) from customer, orders, lineitem where o_orderkey in ( select l_orderkey from lineitem group by l_orderkey having sum(l_quantity) > 142 ) and c_custkey = o_custkey and o_orderkey = l_orderkey group by c_name, c_custkey, o_orderkey, o_orderdate, o_totalprice order by o_totalprice desc, o_orderdate LIMIT 100;
select nation, o_year, sum(amount) as sum_profit from ( select n_name as nation, extract(year from o_orderdate) as o_year, l_extendedprice * (1 - l_discount) - ps_supplycost * l_quantity as amount from part, supplier, lineitem, partsupp, orders, nation where s_suppkey = l_suppkey and ps_suppkey = l_suppkey and ps_partkey = l_partkey and p_partkey = l_partkey and o_orderkey = l_orderkey and s_nationkey = n_nationkey and p_name like '%green%' ) as profit group by nation, o_year order by nation, o_year desc;
select c_count, count(*) as custdist from ( select c_custkey, count(o_orderkey) as c_count from customer left outer join orders on c_custkey = o_custkey and o_comment not like '%express%deposits%' and o_comment not like '%special%accounts%' and o_comment not like '%pending%deposits%' group by c_custkey ) as c_orders group by c_count order by custdist desc, c_count desc;
select p_brand, p_type, p_size, count(distinct ps_suppkey) as supplier_cnt from partsupp, part where p_partkey = ps_partkey and p_brand <> 'Brand#52' and p_type not like 'LARGE POLISHED%' and p_type not like 'ECONOMY ANODIZED%' and p_size in (29, 46, 19, 17, 34, 9, 41, 42) and ps_suppkey not in ( select s_suppkey from supplier where (s_comment like '%Customer%Problems%') ) group by p_brand, p_type, p_size order by supplier_cnt desc, p_brand, p_type, p_size;
select ps_partkey, sum(ps_supplycost * ps_availqty) as value from partsupp, supplier, nation where ps_suppkey = s_suppkey and s_nationkey = n_nationkey and (n_name = 'UNITED KINGDOM') group by ps_partkey having sum(ps_supplycost * ps_availqty) > ( select sum(ps_supplycost * ps_availqty) * 0.0000001209 from partsupp, supplier, nation where ps_suppkey = s_suppkey and s_nationkey = n_nationkey and (n_name = 'UNITED KINGDOM') ) order by value desc;
select nation, o_year, sum(amount) as sum_profit from ( select n_name as nation, extract(year from o_orderdate) as o_year, l_extendedprice * (1 - l_discount) - ps_supplycost * l_quantity as amount from part, supplier, lineitem, partsupp, orders, nation where s_suppkey = l_suppkey and ps_suppkey = l_suppkey and ps_partkey = l_partkey and p_partkey = l_partkey and o_orderkey = l_orderkey and s_nationkey = n_nationkey and p_name like '%brown%' ) as profit group by nation, o_year order by nation, o_year desc;
select supp_nation, cust_nation, l_year, sum(volume) as revenue from ( select n1.n_name as supp_nation, n2.n_name as cust_nation, extract(year from l_shipdate) as l_year, l_extendedprice * (1 - l_discount) as volume from supplier, lineitem, orders, customer, nation n1, nation n2 where s_suppkey = l_suppkey and o_orderkey = l_orderkey and c_custkey = o_custkey and s_nationkey = n1.n_nationkey and c_nationkey = n2.n_nationkey and ((n1.n_name = 'FRANCE' and n2.n_name = 'EGYPT') or (n1.n_name = 'FRANCE' and n2.n_name = 'ARGENTINA')) and l_shipdate between date '1992-01-01' and date '1996-12-31' ) as shipping group by supp_nation, cust_nation, l_year order by supp_nation, cust_nation, l_year;
select c_count, count(*) as custdist from ( select c_custkey, count(o_orderkey) as c_count from customer left outer join orders on c_custkey = o_custkey and o_comment not like '%pending%requests%' and o_comment not like '%special%deposits%' and o_comment not like '%special%packages%' group by c_custkey ) as c_orders group by c_count order by custdist desc, c_count desc;
select nation, o_year, sum(amount) as sum_profit from ( select n_name as nation, extract(year from o_orderdate) as o_year, l_extendedprice * (1 - l_discount) - ps_supplycost * l_quantity as amount from part, supplier, lineitem, partsupp, orders, nation where s_suppkey = l_suppkey and ps_suppkey = l_suppkey and ps_partkey = l_partkey and p_partkey = l_partkey and o_orderkey = l_orderkey and s_nationkey = n_nationkey and p_name like '%red%' ) as profit group by nation, o_year order by nation, o_year desc;
select c_count, count(*) as custdist from ( select c_custkey, count(o_orderkey) as c_count from customer left outer join orders on c_custkey = o_custkey and o_comment not like '%pending%deposits%' group by c_custkey ) as c_orders group by c_count order by custdist desc, c_count desc;
select o_orderpriority, count(*) as order_count from orders where o_orderdate >= date '1995-12-01' and o_orderdate < DATE '1995-12-01' + INTERVAL 3 MONTH and exists ( select * from lineitem where l_orderkey = o_orderkey and l_commitdate < l_receiptdate ) group by o_orderpriority order by o_orderpriority;
select sum(l_extendedprice * (1 - l_discount)) as revenue from lineitem, part where ( p_partkey = l_partkey and p_brand = 'Brand#35' and p_container in ('WRAP JAR', 'WRAP PACK', 'LG DRUM', 'JUMBO CAN', 'SM PACK', 'WRAP PKG', 'SM BAG', 'MED BOX') and l_quantity >= 6 and l_quantity <= 16 and p_size between 1 and 7 and l_shipmode in ('AIR', 'AIR REG') and l_shipinstruct = 'DELIVER IN PERSON' ) or ( p_partkey = l_partkey and p_brand = 'Brand#24' and p_container in ('MED BAG', 'WRAP BAG', 'MED CASE', 'LG PACK', 'MED PACK', 'WRAP CASE', 'LG DRUM', 'WRAP JAR') and l_quantity >= 16 and l_quantity <= 23 and p_size between 1 and 6 and l_shipmode in ('AIR', 'AIR REG') and l_shipinstruct = 'DELIVER IN PERSON' ) or ( p_partkey = l_partkey and p_brand = 'Brand#42' and p_container in ('SM JAR', 'JUMBO BAG', 'LG DRUM', 'SM CASE', 'SM BAG', 'SM BOX', 'SM CAN', 'LG CAN') and l_quantity >= 35 and l_quantity <= 43 and p_size between 1 and 15 and l_shipmode in ('AIR', 'AIR REG') and l_shipinstruct = 'DELIVER IN PERSON' );
select o_orderpriority, count(*) as order_count from orders where o_orderdate >= date '1995-12-01' and o_orderdate < DATE '1995-12-01' + INTERVAL 17 MONTH and exists ( select * from lineitem where l_orderkey = o_orderkey and l_commitdate < l_receiptdate ) group by o_orderpriority order by o_orderpriority;
select p_brand, p_type, p_size, count(distinct ps_suppkey) as supplier_cnt from partsupp, part where p_partkey = ps_partkey and p_brand <> 'Brand#52' and p_type not like 'SMALL BURNISHED%' and p_size in (18, 43, 23, 35, 40, 45, 4, 37) and ps_suppkey not in ( select s_suppkey from supplier where (s_comment like '%Customer%Damages%') ) group by p_brand, p_type, p_size order by supplier_cnt desc, p_brand, p_type, p_size;
select l_shipmode, sum(case when o_orderpriority = '1-URGENT' or o_orderpriority = '2-HIGH' then 1 else 0 end) as high_line_count, sum(case when o_orderpriority <> '1-URGENT' and o_orderpriority <> '2-HIGH' then 1 else 0 end) as low_line_count from orders, lineitem where o_orderkey = l_orderkey and l_shipmode in ('RAIL', 'REG AIR') and l_commitdate < l_receiptdate and l_shipdate < l_commitdate and l_receiptdate >= date '1997-06-23' and l_receiptdate < DATE '1997-06-23' + INTERVAL 4 YEAR group by l_shipmode order by l_shipmode;
select c_count, count(*) as custdist from ( select c_custkey, count(o_orderkey) as c_count from customer left outer join orders on c_custkey = o_custkey and o_comment not like '%pending%requests%' and o_comment not like '%unusual%deposits%' group by c_custkey ) as c_orders group by c_count order by custdist desc, c_count desc;
select c_name, c_custkey, o_orderkey, o_orderdate, o_totalprice, sum(l_quantity) from customer, orders, lineitem where o_orderkey in ( select l_orderkey from lineitem group by l_orderkey having sum(l_quantity) > 109 ) and c_custkey = o_custkey and o_orderkey = l_orderkey group by c_name, c_custkey, o_orderkey, o_orderdate, o_totalprice order by o_totalprice desc, o_orderdate LIMIT 100;
select p_brand, p_type, p_size, count(distinct ps_suppkey) as supplier_cnt from partsupp, part where p_partkey = ps_partkey and p_brand <> 'Brand#52' and p_type not like 'ECONOMY ANODIZED%' and p_type not like 'MEDIUM POLISHED%' and p_type not like 'STANDARD POLISHED%' and p_size in (28, 19, 11, 23, 39, 5, 42, 36) and ps_suppkey not in ( select s_suppkey from supplier where (s_comment like '%Customer%Issues%' or s_comment like '%Customer%Damages%' or s_comment like '%Customer%Problems%') ) group by p_brand, p_type, p_size order by supplier_cnt desc, p_brand, p_type, p_size;
select o_orderpriority, count(*) as order_count from orders where o_orderdate >= date '1995-12-01' and o_orderdate < DATE '1995-12-01' + INTERVAL 4 MONTH and exists ( select * from lineitem where l_orderkey = o_orderkey and l_commitdate < l_receiptdate ) group by o_orderpriority order by o_orderpriority;
select s_name, s_address from supplier, nation where s_suppkey in ( select ps_suppkey from partsupp where ps_partkey in ( select p_partkey from part where (p_name like '%purple%' or p_name like '%pink%' or p_name like '%red%' or p_name like '%lavender%') ) and ps_availqty > ( select 0.5 * sum(l_quantity) from lineitem where l_partkey = ps_partkey and l_suppkey = ps_suppkey and l_shipdate >= date '1992-12-08' and l_shipdate < DATE '1992-12-08' + INTERVAL 4 YEAR ) ) and s_nationkey = n_nationkey and n_name = 'CHINA' order by s_name;
select l_returnflag, l_linestatus, sum(l_quantity) as sum_qty, sum(l_extendedprice) as sum_base_price, sum(l_extendedprice * (1 - l_discount)) as sum_disc_price, sum(l_extendedprice * (1 - l_discount) * (1 + l_tax)) as sum_charge, avg(l_quantity) as avg_qty, avg(l_extendedprice) as avg_price, avg(l_discount) as avg_disc, count(*) as count_order from lineitem where l_shipdate <= DATE '1995-04-05' - INTERVAL 99 DAY group by l_returnflag, l_linestatus order by l_returnflag, l_linestatus;
select supp_nation, cust_nation, l_year, sum(volume) as revenue from ( select n1.n_name as supp_nation, n2.n_name as cust_nation, extract(year from l_shipdate) as l_year, l_extendedprice * (1 - l_discount) as volume from supplier, lineitem, orders, customer, nation n1, nation n2 where s_suppkey = l_suppkey and o_orderkey = l_orderkey and c_custkey = o_custkey and s_nationkey = n1.n_nationkey and c_nationkey = n2.n_nationkey and ((n1.n_name = 'GERMANY' and n2.n_name = 'MOROCCO') or (n1.n_name = 'MOROCCO' and n2.n_name = 'GERMANY')) and l_shipdate between date '1993-01-01' and date '1998-12-31' ) as shipping group by supp_nation, cust_nation, l_year order by supp_nation, cust_nation, l_year;
select sum(l_extendedprice * l_discount) as revenue from lineitem where l_shipdate >= date '1992-10-05' and l_shipdate < DATE '1992-10-05' + INTERVAL 4 YEAR and l_discount between 0.02 - 0.01 and 0.02 + 0.01 and l_quantity < 21;
select p_brand, p_type, p_size, count(distinct ps_suppkey) as supplier_cnt from partsupp, part where p_partkey = ps_partkey and p_brand <> 'Brand#52' and p_type not like 'STANDARD POLISHED%' and p_type not like 'LARGE POLISHED%' and p_type not like 'SMALL BURNISHED%' and p_size in (3, 40, 39, 41, 45, 38, 14, 33) and ps_suppkey not in ( select s_suppkey from supplier where (s_comment like '%Customer%Returns%' or s_comment like '%Customer%Dislikes%' or s_comment like '%Customer%Damages%') ) group by p_brand, p_type, p_size order by supplier_cnt desc, p_brand, p_type, p_size;
select s_name, s_address from supplier, nation where s_suppkey in ( select ps_suppkey from partsupp where ps_partkey in ( select p_partkey from part where (p_name like '%pink%' or p_name like '%green%' or p_name like '%red%') ) and ps_availqty > ( select 0.5 * sum(l_quantity) from lineitem where l_partkey = ps_partkey and l_suppkey = ps_suppkey and l_shipdate >= date '1992-04-26' and l_shipdate < DATE '1992-04-26' + INTERVAL 1 YEAR ) ) and s_nationkey = n_nationkey and n_name = 'CHINA' order by s_name;
select p_brand, p_type, p_size, count(distinct ps_suppkey) as supplier_cnt from partsupp, part where p_partkey = ps_partkey and p_brand <> 'Brand#52' and p_type not like 'MEDIUM POLISHED%' and p_type not like 'SMALL BURNISHED%' and p_type not like 'LARGE POLISHED%' and p_size in (47, 6, 46, 41, 10, 27, 9, 21) and ps_suppkey not in ( select s_suppkey from supplier where (s_comment like '%Customer%Problems%') ) group by p_brand, p_type, p_size order by supplier_cnt desc, p_brand, p_type, p_size;
select supp_nation, cust_nation, l_year, sum(volume) as revenue from ( select n1.n_name as supp_nation, n2.n_name as cust_nation, extract(year from l_shipdate) as l_year, l_extendedprice * (1 - l_discount) as volume from supplier, lineitem, orders, customer, nation n1, nation n2 where s_suppkey = l_suppkey and o_orderkey = l_orderkey and c_custkey = o_custkey and s_nationkey = n1.n_nationkey and c_nationkey = n2.n_nationkey and ((n1.n_name = 'MOZAMBIQUE' and n2.n_name = 'UNITED KINGDOM') or (n1.n_name = 'MOZAMBIQUE' and n2.n_name = 'FRANCE')) and l_shipdate between date '1993-01-01' and date '1998-12-31' ) as shipping group by supp_nation, cust_nation, l_year order by supp_nation, cust_nation, l_year;
select supp_nation, cust_nation, l_year, sum(volume) as revenue from ( select n1.n_name as supp_nation, n2.n_name as cust_nation, extract(year from l_shipdate) as l_year, l_extendedprice * (1 - l_discount) as volume from supplier, lineitem, orders, customer, nation n1, nation n2 where s_suppkey = l_suppkey and o_orderkey = l_orderkey and c_custkey = o_custkey and s_nationkey = n1.n_nationkey and c_nationkey = n2.n_nationkey and ((n1.n_name = 'UNITED STATES' and n2.n_name = 'PERU') or (n1.n_name = 'PERU' and n2.n_name = 'UNITED STATES')) and l_shipdate between date '1997-01-01' and date '1998-12-31' ) as shipping group by supp_nation, cust_nation, l_year order by supp_nation, cust_nation, l_year;
select ps_partkey, sum(ps_supplycost * ps_availqty) as value from partsupp, supplier, nation where ps_suppkey = s_suppkey and s_nationkey = n_nationkey and (n_name = 'RUSSIA' or n_name = 'ROMANIA' or n_name = 'MOROCCO') group by ps_partkey having sum(ps_supplycost * ps_availqty) > ( select sum(ps_supplycost * ps_availqty) * 0.0000005997 from partsupp, supplier, nation where ps_suppkey = s_suppkey and s_nationkey = n_nationkey and (n_name = 'RUSSIA' or n_name = 'ROMANIA' or n_name = 'MOROCCO') ) order by value desc;
select nation, o_year, sum(amount) as sum_profit from ( select n_name as nation, extract(year from o_orderdate) as o_year, l_extendedprice * (1 - l_discount) - ps_supplycost * l_quantity as amount from part, supplier, lineitem, partsupp, orders, nation where s_suppkey = l_suppkey and ps_suppkey = l_suppkey and ps_partkey = l_partkey and p_partkey = l_partkey and o_orderkey = l_orderkey and s_nationkey = n_nationkey and p_name like '%red%' ) as profit group by nation, o_year order by nation, o_year desc;
select sum(l_extendedprice * (1 - l_discount)) as revenue from lineitem, part where ( p_partkey = l_partkey and p_brand = 'Brand#35' and p_container in ('LG PACK', 'LG CASE', 'WRAP PACK', 'JUMBO CASE') and l_quantity >= 11 and l_quantity <= 20 and p_size between 1 and 3 and l_shipmode in ('AIR', 'AIR REG') and l_shipinstruct = 'DELIVER IN PERSON' ) or ( p_partkey = l_partkey and p_brand = 'Brand#24' and p_container in ('WRAP JAR', 'MED JAR', 'MED PACK', 'JUMBO CASE') and l_quantity >= 15 and l_quantity <= 21 and p_size between 1 and 10 and l_shipmode in ('AIR', 'AIR REG') and l_shipinstruct = 'DELIVER IN PERSON' ) or ( p_partkey = l_partkey and p_brand = 'Brand#42' and p_container in ('MED CAN', 'MED PACK', 'SM CASE', 'WRAP PACK') and l_quantity >= 30 and l_quantity <= 41 and p_size between 1 and 15 and l_shipmode in ('AIR', 'AIR REG') and l_shipinstruct = 'DELIVER IN PERSON' );
select 100.00 * sum(case when p_type like 'PROMO%' then l_extendedprice * (1 - l_discount) else 0 end) / sum(l_extendedprice * (1 - l_discount)) as promo_revenue from lineitem, part where l_partkey = p_partkey and l_shipdate >= date '1993-03-16' and l_shipdate < DATE '1993-03-16' + INTERVAL 16 MONTH;
select l_shipmode, sum(case when o_orderpriority = '1-URGENT' or o_orderpriority = '2-HIGH' then 1 else 0 end) as high_line_count, sum(case when o_orderpriority <> '1-URGENT' and o_orderpriority <> '2-HIGH' then 1 else 0 end) as low_line_count from orders, lineitem where o_orderkey = l_orderkey and l_shipmode in ('FOB', 'RAIL', 'REG AIR') and l_commitdate < l_receiptdate and l_shipdate < l_commitdate and l_receiptdate >= date '1994-04-23' and l_receiptdate < DATE '1994-04-23' + INTERVAL 5 YEAR group by l_shipmode order by l_shipmode;
select o_orderpriority, count(*) as order_count from orders where o_orderdate >= date '1995-12-01' and o_orderdate < DATE '1995-12-01' + INTERVAL 34 MONTH and exists ( select * from lineitem where l_orderkey = o_orderkey and l_commitdate < l_receiptdate ) group by o_orderpriority order by o_orderpriority;
select sum(l_extendedprice * l_discount) as revenue from lineitem where l_shipdate >= date '1995-06-21' and l_shipdate < DATE '1995-06-21' + INTERVAL 1 YEAR and l_discount between 0.07 - 0.02 and 0.07 + 0.02 and l_quantity < 25;
select s_name, s_address from supplier, nation where s_suppkey in ( select ps_suppkey from partsupp where ps_partkey in ( select p_partkey from part where (p_name like '%red%') ) and ps_availqty > ( select 0.5 * sum(l_quantity) from lineitem where l_partkey = ps_partkey and l_suppkey = ps_suppkey and l_shipdate >= date '1994-05-04' and l_shipdate < DATE '1994-05-04' + INTERVAL 4 YEAR ) ) and s_nationkey = n_nationkey and n_name = 'CHINA' order by s_name;
select 100.00 * sum(case when p_type like 'PROMO%' then l_extendedprice * (1 - l_discount) else 0 end) / sum(l_extendedprice * (1 - l_discount)) as promo_revenue from lineitem, part where l_partkey = p_partkey and l_shipdate >= date '1992-07-30' and l_shipdate < DATE '1992-07-30' + INTERVAL 8 MONTH;
select sum(l_extendedprice * l_discount) as revenue from lineitem where l_shipdate >= date '1997-06-13' and l_shipdate < DATE '1997-06-13' + INTERVAL 3 YEAR and l_discount between 0.04 - 0.01 and 0.04 + 0.01 and l_quantity < 22;
select c_name, c_custkey, o_orderkey, o_orderdate, o_totalprice, sum(l_quantity) from customer, orders, lineitem where o_orderkey in ( select l_orderkey from lineitem group by l_orderkey having sum(l_quantity) > 86 ) and c_custkey = o_custkey and o_orderkey = l_orderkey group by c_name, c_custkey, o_orderkey, o_orderdate, o_totalprice order by o_totalprice desc, o_orderdate LIMIT 100;
select s_acctbal, s_name, n_name, p_partkey, p_mfgr, s_address, s_phone, s_comment from part, supplier, partsupp, nation, region where p_partkey = ps_partkey and s_suppkey = ps_suppkey and p_size = 50 and (p_type like '%STEEL' or p_type like '%BRASS') and s_nationkey = n_nationkey and n_regionkey = r_regionkey and (r_name = 'AMERICA') and ps_supplycost = ( select min(ps_supplycost) from partsupp, supplier, nation, region where p_partkey = ps_partkey and s_suppkey = ps_suppkey and s_nationkey = n_nationkey and n_regionkey = r_regionkey and (r_name = 'AMERICA') ) order by s_acctbal desc, n_name, s_name, p_partkey LIMIT 100;
select ps_partkey, sum(ps_supplycost * ps_availqty) as value from partsupp, supplier, nation where ps_suppkey = s_suppkey and s_nationkey = n_nationkey and (n_name = 'CANADA') group by ps_partkey having sum(ps_supplycost * ps_availqty) > ( select sum(ps_supplycost * ps_availqty) * 0.0000023683 from partsupp, supplier, nation where ps_suppkey = s_suppkey and s_nationkey = n_nationkey and (n_name = 'CANADA') ) order by value desc;
select o_orderpriority, count(*) as order_count from orders where o_orderdate >= date '1995-12-01' and o_orderdate < DATE '1995-12-01' + INTERVAL 35 MONTH and exists ( select * from lineitem where l_orderkey = o_orderkey and l_commitdate < l_receiptdate ) group by o_orderpriority order by o_orderpriority;
select 100.00 * sum(case when p_type like 'PROMO%' then l_extendedprice * (1 - l_discount) else 0 end) / sum(l_extendedprice * (1 - l_discount)) as promo_revenue from lineitem, part where l_partkey = p_partkey and l_shipdate >= date '1992-04-13' and l_shipdate < DATE '1992-04-13' + INTERVAL 50 MONTH;
select ps_partkey, sum(ps_supplycost * ps_availqty) as value from partsupp, supplier, nation where ps_suppkey = s_suppkey and s_nationkey = n_nationkey and (n_name = 'IRAN') group by ps_partkey having sum(ps_supplycost * ps_availqty) > ( select sum(ps_supplycost * ps_availqty) * 0.0000024829 from partsupp, supplier, nation where ps_suppkey = s_suppkey and s_nationkey = n_nationkey and (n_name = 'IRAN') ) order by value desc;
select 100.00 * sum(case when p_type like 'PROMO%' then l_extendedprice * (1 - l_discount) else 0 end) / sum(l_extendedprice * (1 - l_discount)) as promo_revenue from lineitem, part where l_partkey = p_partkey and l_shipdate >= date '1992-12-21' and l_shipdate < DATE '1992-12-21' + INTERVAL 34 MONTH;
select l_shipmode, sum(case when o_orderpriority = '1-URGENT' or o_orderpriority = '2-HIGH' then 1 else 0 end) as high_line_count, sum(case when o_orderpriority <> '1-URGENT' and o_orderpriority <> '2-HIGH' then 1 else 0 end) as low_line_count from orders, lineitem where o_orderkey = l_orderkey and l_shipmode in ('SHIP', 'REG AIR') and l_commitdate < l_receiptdate and l_shipdate < l_commitdate and l_receiptdate >= date '1997-02-19' and l_receiptdate < DATE '1997-02-19' + INTERVAL 5 YEAR group by l_shipmode order by l_shipmode;
select c_name, c_custkey, o_orderkey, o_orderdate, o_totalprice, sum(l_quantity) from customer, orders, lineitem where o_orderkey in ( select l_orderkey from lineitem group by l_orderkey having sum(l_quantity) > 76 ) and c_custkey = o_custkey and o_orderkey = l_orderkey group by c_name, c_custkey, o_orderkey, o_orderdate, o_totalprice order by o_totalprice desc, o_orderdate LIMIT 100;
select nation, o_year, sum(amount) as sum_profit from ( select n_name as nation, extract(year from o_orderdate) as o_year, l_extendedprice * (1 - l_discount) - ps_supplycost * l_quantity as amount from part, supplier, lineitem, partsupp, orders, nation where s_suppkey = l_suppkey and ps_suppkey = l_suppkey and ps_partkey = l_partkey and p_partkey = l_partkey and o_orderkey = l_orderkey and s_nationkey = n_nationkey and p_name like '%yellow%' ) as profit group by nation, o_year order by nation, o_year desc;
select p_brand, p_type, p_size, count(distinct ps_suppkey) as supplier_cnt from partsupp, part where p_partkey = ps_partkey and p_brand <> 'Brand#52' and p_type not like 'LARGE POLISHED%' and p_type not like 'MEDIUM POLISHED%' and p_size in (49, 2, 22, 4, 41, 3, 12, 43) and ps_suppkey not in ( select s_suppkey from supplier where (s_comment like '%Customer%Problems%' or s_comment like '%Customer%Damages%' or s_comment like '%Customer%Returns%') ) group by p_brand, p_type, p_size order by supplier_cnt desc, p_brand, p_type, p_size;
select l_shipmode, sum(case when o_orderpriority = '1-URGENT' or o_orderpriority = '2-HIGH' then 1 else 0 end) as high_line_count, sum(case when o_orderpriority <> '1-URGENT' and o_orderpriority <> '2-HIGH' then 1 else 0 end) as low_line_count from orders, lineitem where o_orderkey = l_orderkey and l_shipmode in ('TRUCK', 'AIR') and l_commitdate < l_receiptdate and l_shipdate < l_commitdate and l_receiptdate >= date '1995-11-02' and l_receiptdate < DATE '1995-11-02' + INTERVAL 1 YEAR group by l_shipmode order by l_shipmode;
select ps_partkey, sum(ps_supplycost * ps_availqty) as value from partsupp, supplier, nation where ps_suppkey = s_suppkey and s_nationkey = n_nationkey and (n_name = 'ROMANIA' or n_name = 'INDIA') group by ps_partkey having sum(ps_supplycost * ps_availqty) > ( select sum(ps_supplycost * ps_availqty) * 0.0000003946 from partsupp, supplier, nation where ps_suppkey = s_suppkey and s_nationkey = n_nationkey and (n_name = 'ROMANIA' or n_name = 'INDIA') ) order by value desc;
select s_acctbal, s_name, n_name, p_partkey, p_mfgr, s_address, s_phone, s_comment from part, supplier, partsupp, nation, region where p_partkey = ps_partkey and s_suppkey = ps_suppkey and p_size = 43 and (p_type like '%NICKEL') and s_nationkey = n_nationkey and n_regionkey = r_regionkey and (r_name = 'ASIA' or r_name = 'EUROPE' or r_name = 'AFRICA') and ps_supplycost = ( select min(ps_supplycost) from partsupp, supplier, nation, region where p_partkey = ps_partkey and s_suppkey = ps_suppkey and s_nationkey = n_nationkey and n_regionkey = r_regionkey and (r_name = 'ASIA' or r_name = 'EUROPE' or r_name = 'AFRICA') ) order by s_acctbal desc, n_name, s_name, p_partkey LIMIT 100;
select l_returnflag, l_linestatus, sum(l_quantity) as sum_qty, sum(l_extendedprice) as sum_base_price, sum(l_extendedprice * (1 - l_discount)) as sum_disc_price, sum(l_extendedprice * (1 - l_discount) * (1 + l_tax)) as sum_charge, avg(l_quantity) as avg_qty, avg(l_extendedprice) as avg_price, avg(l_discount) as avg_disc, count(*) as count_order from lineitem where l_shipdate <= DATE '1997-02-12' - INTERVAL 99 DAY group by l_returnflag, l_linestatus order by l_returnflag, l_linestatus;
select l_shipmode, sum(case when o_orderpriority = '1-URGENT' or o_orderpriority = '2-HIGH' then 1 else 0 end) as high_line_count, sum(case when o_orderpriority <> '1-URGENT' and o_orderpriority <> '2-HIGH' then 1 else 0 end) as low_line_count from orders, lineitem where o_orderkey = l_orderkey and l_shipmode in ('TRUCK', 'MAIL', 'FOB') and l_commitdate < l_receiptdate and l_shipdate < l_commitdate and l_receiptdate >= date '1993-09-04' and l_receiptdate < DATE '1993-09-04' + INTERVAL 5 YEAR group by l_shipmode order by l_shipmode;
select l_returnflag, l_linestatus, sum(l_quantity) as sum_qty, sum(l_extendedprice) as sum_base_price, sum(l_extendedprice * (1 - l_discount)) as sum_disc_price, sum(l_extendedprice * (1 - l_discount) * (1 + l_tax)) as sum_charge, avg(l_quantity) as avg_qty, avg(l_extendedprice) as avg_price, avg(l_discount) as avg_disc, count(*) as count_order from lineitem where l_shipdate <= DATE '1996-04-17' - INTERVAL 99 DAY group by l_returnflag, l_linestatus order by l_returnflag, l_linestatus;
select nation, o_year, sum(amount) as sum_profit from ( select n_name as nation, extract(year from o_orderdate) as o_year, l_extendedprice * (1 - l_discount) - ps_supplycost * l_quantity as amount from part, supplier, lineitem, partsupp, orders, nation where s_suppkey = l_suppkey and ps_suppkey = l_suppkey and ps_partkey = l_partkey and p_partkey = l_partkey and o_orderkey = l_orderkey and s_nationkey = n_nationkey and p_name like '%lavender%' ) as profit group by nation, o_year order by nation, o_year desc;
select sum(l_extendedprice * (1 - l_discount)) as revenue from lineitem, part where ( p_partkey = l_partkey and p_brand = 'Brand#35' and p_container in ('WRAP BOX', 'MED DRUM', 'SM BOX', 'LG DRUM', 'LG PKG', 'SM BAG') and l_quantity >= 3 and l_quantity <= 8 and p_size between 1 and 4 and l_shipmode in ('AIR', 'AIR REG') and l_shipinstruct = 'DELIVER IN PERSON' ) or ( p_partkey = l_partkey and p_brand = 'Brand#24' and p_container in ('MED JAR', 'SM CASE', 'LG CASE', 'JUMBO BOX', 'SM PKG', 'WRAP PKG') and l_quantity >= 22 and l_quantity <= 34 and p_size between 1 and 7 and l_shipmode in ('AIR', 'AIR REG') and l_shipinstruct = 'DELIVER IN PERSON' ) or ( p_partkey = l_partkey and p_brand = 'Brand#42' and p_container in ('MED BOX', 'JUMBO DRUM', 'MED PACK', 'MED CAN', 'SM CASE', 'MED JAR') and l_quantity >= 34 and l_quantity <= 41 and p_size between 1 and 25 and l_shipmode in ('AIR', 'AIR REG') and l_shipinstruct = 'DELIVER IN PERSON' );
select nation, o_year, sum(amount) as sum_profit from ( select n_name as nation, extract(year from o_orderdate) as o_year, l_extendedprice * (1 - l_discount) - ps_supplycost * l_quantity as amount from part, supplier, lineitem, partsupp, orders, nation where s_suppkey = l_suppkey and ps_suppkey = l_suppkey and ps_partkey = l_partkey and p_partkey = l_partkey and o_orderkey = l_orderkey and s_nationkey = n_nationkey and p_name like '%pink%' ) as profit group by nation, o_year order by nation, o_year desc;
select sum(l_extendedprice * l_discount) as revenue from lineitem where l_shipdate >= date '1996-04-06' and l_shipdate < DATE '1996-04-06' + INTERVAL 1 YEAR and l_discount between 0.02 - 0.03 and 0.02 + 0.03 and l_quantity < 23;
select supp_nation, cust_nation, l_year, sum(volume) as revenue from ( select n1.n_name as supp_nation, n2.n_name as cust_nation, extract(year from l_shipdate) as l_year, l_extendedprice * (1 - l_discount) as volume from supplier, lineitem, orders, customer, nation n1, nation n2 where s_suppkey = l_suppkey and o_orderkey = l_orderkey and c_custkey = o_custkey and s_nationkey = n1.n_nationkey and c_nationkey = n2.n_nationkey and ((n1.n_name = 'ARGENTINA' and n2.n_name = 'RUSSIA') or (n1.n_name = 'ROMANIA' and n2.n_name = 'RUSSIA')) and l_shipdate between date '1997-01-01' and date '1998-12-31' ) as shipping group by supp_nation, cust_nation, l_year order by supp_nation, cust_nation, l_year;
select l_shipmode, sum(case when o_orderpriority = '1-URGENT' or o_orderpriority = '2-HIGH' then 1 else 0 end) as high_line_count, sum(case when o_orderpriority <> '1-URGENT' and o_orderpriority <> '2-HIGH' then 1 else 0 end) as low_line_count from orders, lineitem where o_orderkey = l_orderkey and l_shipmode in ('REG AIR', 'TRUCK', 'SHIP', 'AIR') and l_commitdate < l_receiptdate and l_shipdate < l_commitdate and l_receiptdate >= date '1998-08-23' and l_receiptdate < DATE '1998-08-23' + INTERVAL 6 YEAR group by l_shipmode order by l_shipmode;
select l_shipmode, sum(case when o_orderpriority = '1-URGENT' or o_orderpriority = '2-HIGH' then 1 else 0 end) as high_line_count, sum(case when o_orderpriority <> '1-URGENT' and o_orderpriority <> '2-HIGH' then 1 else 0 end) as low_line_count from orders, lineitem where o_orderkey = l_orderkey and l_shipmode in ('REG AIR', 'RAIL', 'FOB', 'TRUCK') and l_commitdate < l_receiptdate and l_shipdate < l_commitdate and l_receiptdate >= date '1994-02-20' and l_receiptdate < DATE '1994-02-20' + INTERVAL 5 YEAR group by l_shipmode order by l_shipmode;
select sum(l_extendedprice * (1 - l_discount)) as revenue from lineitem, part where ( p_partkey = l_partkey and p_brand = 'Brand#35' and p_container in ('SM CAN', 'WRAP BOX', 'WRAP JAR', 'SM JAR', 'SM DRUM') and l_quantity >= 11 and l_quantity <= 19 and p_size between 1 and 4 and l_shipmode in ('AIR', 'AIR REG') and l_shipinstruct = 'DELIVER IN PERSON' ) or ( p_partkey = l_partkey and p_brand = 'Brand#24' and p_container in ('WRAP PACK', 'LG BAG', 'SM PACK', 'LG BOX', 'MED DRUM') and l_quantity >= 14 and l_quantity <= 24 and p_size between 1 and 12 and l_shipmode in ('AIR', 'AIR REG') and l_shipinstruct = 'DELIVER IN PERSON' ) or ( p_partkey = l_partkey and p_brand = 'Brand#42' and p_container in ('JUMBO CAN', 'SM BOX', 'SM CASE', 'WRAP DRUM', 'WRAP PACK') and l_quantity >= 32 and l_quantity <= 40 and p_size between 1 and 22 and l_shipmode in ('AIR', 'AIR REG') and l_shipinstruct = 'DELIVER IN PERSON' );
select nation, o_year, sum(amount) as sum_profit from ( select n_name as nation, extract(year from o_orderdate) as o_year, l_extendedprice * (1 - l_discount) - ps_supplycost * l_quantity as amount from part, supplier, lineitem, partsupp, orders, nation where s_suppkey = l_suppkey and ps_suppkey = l_suppkey and ps_partkey = l_partkey and p_partkey = l_partkey and o_orderkey = l_orderkey and s_nationkey = n_nationkey and p_name like '%purple%' ) as profit group by nation, o_year order by nation, o_year desc;
select s_acctbal, s_name, n_name, p_partkey, p_mfgr, s_address, s_phone, s_comment from part, supplier, partsupp, nation, region where p_partkey = ps_partkey and s_suppkey = ps_suppkey and p_size = 28 and (p_type like '%COPPER') and s_nationkey = n_nationkey and n_regionkey = r_regionkey and (r_name = 'EUROPE' or r_name = 'ASIA' or r_name = 'MIDDLE EAST') and ps_supplycost = ( select min(ps_supplycost) from partsupp, supplier, nation, region where p_partkey = ps_partkey and s_suppkey = ps_suppkey and s_nationkey = n_nationkey and n_regionkey = r_regionkey and (r_name = 'EUROPE' or r_name = 'ASIA' or r_name = 'MIDDLE EAST') ) order by s_acctbal desc, n_name, s_name, p_partkey LIMIT 100;
select sum(l_extendedprice * l_discount) as revenue from lineitem where l_shipdate >= date '1995-04-26' and l_shipdate < DATE '1995-04-26' + INTERVAL 5 YEAR and l_discount between 0.05 - 0.02 and 0.05 + 0.02 and l_quantity < 25;
select supp_nation, cust_nation, l_year, sum(volume) as revenue from ( select n1.n_name as supp_nation, n2.n_name as cust_nation, extract(year from l_shipdate) as l_year, l_extendedprice * (1 - l_discount) as volume from supplier, lineitem, orders, customer, nation n1, nation n2 where s_suppkey = l_suppkey and o_orderkey = l_orderkey and c_custkey = o_custkey and s_nationkey = n1.n_nationkey and c_nationkey = n2.n_nationkey and ((n1.n_name = 'INDIA' and n2.n_name = 'IRAQ') or (n1.n_name = 'IRAQ' and n2.n_name = 'INDIA')) and l_shipdate between date '1997-01-01' and date '1998-12-31' ) as shipping group by supp_nation, cust_nation, l_year order by supp_nation, cust_nation, l_year;
select supp_nation, cust_nation, l_year, sum(volume) as revenue from ( select n1.n_name as supp_nation, n2.n_name as cust_nation, extract(year from l_shipdate) as l_year, l_extendedprice * (1 - l_discount) as volume from supplier, lineitem, orders, customer, nation n1, nation n2 where s_suppkey = l_suppkey and o_orderkey = l_orderkey and c_custkey = o_custkey and s_nationkey = n1.n_nationkey and c_nationkey = n2.n_nationkey and ((n1.n_name = 'IRAN' and n2.n_name = 'FRANCE') or (n1.n_name = 'IRAN' and n2.n_name = 'EGYPT')) and l_shipdate between date '1997-01-01' and date '1997-12-31' ) as shipping group by supp_nation, cust_nation, l_year order by supp_nation, cust_nation, l_year;
select l_returnflag, l_linestatus, sum(l_quantity) as sum_qty, sum(l_extendedprice) as sum_base_price, sum(l_extendedprice * (1 - l_discount)) as sum_disc_price, sum(l_extendedprice * (1 - l_discount) * (1 + l_tax)) as sum_charge, avg(l_quantity) as avg_qty, avg(l_extendedprice) as avg_price, avg(l_discount) as avg_disc, count(*) as count_order from lineitem where l_shipdate <= DATE '1997-07-08' - INTERVAL 99 DAY group by l_returnflag, l_linestatus order by l_returnflag, l_linestatus;
select l_returnflag, l_linestatus, sum(l_quantity) as sum_qty, sum(l_extendedprice) as sum_base_price, sum(l_extendedprice * (1 - l_discount)) as sum_disc_price, sum(l_extendedprice * (1 - l_discount) * (1 + l_tax)) as sum_charge, avg(l_quantity) as avg_qty, avg(l_extendedprice) as avg_price, avg(l_discount) as avg_disc, count(*) as count_order from lineitem where l_shipdate <= DATE '1998-03-29' - INTERVAL 99 DAY group by l_returnflag, l_linestatus order by l_returnflag, l_linestatus;
select l_shipmode, sum(case when o_orderpriority = '1-URGENT' or o_orderpriority = '2-HIGH' then 1 else 0 end) as high_line_count, sum(case when o_orderpriority <> '1-URGENT' and o_orderpriority <> '2-HIGH' then 1 else 0 end) as low_line_count from orders, lineitem where o_orderkey = l_orderkey and l_shipmode in ('REG AIR', 'SHIP') and l_commitdate < l_receiptdate and l_shipdate < l_commitdate and l_receiptdate >= date '1995-02-11' and l_receiptdate < DATE '1995-02-11' + INTERVAL 5 YEAR group by l_shipmode order by l_shipmode;
select ps_partkey, sum(ps_supplycost * ps_availqty) as value from partsupp, supplier, nation where ps_suppkey = s_suppkey and s_nationkey = n_nationkey and (n_name = 'UNITED KINGDOM') group by ps_partkey having sum(ps_supplycost * ps_availqty) > ( select sum(ps_supplycost * ps_availqty) * 0.0000008780 from partsupp, supplier, nation where ps_suppkey = s_suppkey and s_nationkey = n_nationkey and (n_name = 'UNITED KINGDOM') ) order by value desc;
select sum(l_extendedprice * l_discount) as revenue from lineitem where l_shipdate >= date '1994-05-26' and l_shipdate < DATE '1994-05-26' + INTERVAL 5 YEAR and l_discount between 0.06 - 0.02 and 0.06 + 0.02 and l_quantity < 21;
select 100.00 * sum(case when p_type like 'PROMO%' then l_extendedprice * (1 - l_discount) else 0 end) / sum(l_extendedprice * (1 - l_discount)) as promo_revenue from lineitem, part where l_partkey = p_partkey and l_shipdate >= date '1993-06-06' and l_shipdate < DATE '1993-06-06' + INTERVAL 30 MONTH;
select nation, o_year, sum(amount) as sum_profit from ( select n_name as nation, extract(year from o_orderdate) as o_year, l_extendedprice * (1 - l_discount) - ps_supplycost * l_quantity as amount from part, supplier, lineitem, partsupp, orders, nation where s_suppkey = l_suppkey and ps_suppkey = l_suppkey and ps_partkey = l_partkey and p_partkey = l_partkey and o_orderkey = l_orderkey and s_nationkey = n_nationkey and p_name like '%lavender%' ) as profit group by nation, o_year order by nation, o_year desc;
select supp_nation, cust_nation, l_year, sum(volume) as revenue from ( select n1.n_name as supp_nation, n2.n_name as cust_nation, extract(year from l_shipdate) as l_year, l_extendedprice * (1 - l_discount) as volume from supplier, lineitem, orders, customer, nation n1, nation n2 where s_suppkey = l_suppkey and o_orderkey = l_orderkey and c_custkey = o_custkey and s_nationkey = n1.n_nationkey and c_nationkey = n2.n_nationkey and ((n1.n_name = 'ROMANIA' and n2.n_name = 'ARGENTINA') or (n1.n_name = 'ROMANIA' and n2.n_name = 'JAPAN')) and l_shipdate between date '1997-01-01' and date '1998-12-31' ) as shipping group by supp_nation, cust_nation, l_year order by supp_nation, cust_nation, l_year;
select sum(l_extendedprice) / 7.0 as avg_yearly from lineitem, part where p_partkey = l_partkey and p_brand = 'Brand#24' and (p_container = 'SM PACK') and l_quantity < ( select 0.2 * avg(l_quantity) from lineitem where l_partkey = p_partkey );
select c_count, count(*) as custdist from ( select c_custkey, count(o_orderkey) as c_count from customer left outer join orders on c_custkey = o_custkey and o_comment not like '%special%packages%' and o_comment not like '%express%deposits%' group by c_custkey ) as c_orders group by c_count order by custdist desc, c_count desc;
select p_brand, p_type, p_size, count(distinct ps_suppkey) as supplier_cnt from partsupp, part where p_partkey = ps_partkey and p_brand <> 'Brand#52' and p_type not like 'SMALL BURNISHED%' and p_type not like 'STANDARD POLISHED%' and p_size in (38, 16, 47, 45, 13, 22, 42, 32) and ps_suppkey not in ( select s_suppkey from supplier where (s_comment like '%Customer%Complaints%') ) group by p_brand, p_type, p_size order by supplier_cnt desc, p_brand, p_type, p_size;
select l_shipmode, sum(case when o_orderpriority = '1-URGENT' or o_orderpriority = '2-HIGH' then 1 else 0 end) as high_line_count, sum(case when o_orderpriority <> '1-URGENT' and o_orderpriority <> '2-HIGH' then 1 else 0 end) as low_line_count from orders, lineitem where o_orderkey = l_orderkey and l_shipmode in ('FOB', 'REG AIR') and l_commitdate < l_receiptdate and l_shipdate < l_commitdate and l_receiptdate >= date '1993-04-25' and l_receiptdate < DATE '1993-04-25' + INTERVAL 4 YEAR group by l_shipmode order by l_shipmode;
select l_shipmode, sum(case when o_orderpriority = '1-URGENT' or o_orderpriority = '2-HIGH' then 1 else 0 end) as high_line_count, sum(case when o_orderpriority <> '1-URGENT' and o_orderpriority <> '2-HIGH' then 1 else 0 end) as low_line_count from orders, lineitem where o_orderkey = l_orderkey and l_shipmode in ('SHIP', 'MAIL', 'REG AIR', 'RAIL') and l_commitdate < l_receiptdate and l_shipdate < l_commitdate and l_receiptdate >= date '1994-04-03' and l_receiptdate < DATE '1994-04-03' + INTERVAL 6 YEAR group by l_shipmode order by l_shipmode;
select l_shipmode, sum(case when o_orderpriority = '1-URGENT' or o_orderpriority = '2-HIGH' then 1 else 0 end) as high_line_count, sum(case when o_orderpriority <> '1-URGENT' and o_orderpriority <> '2-HIGH' then 1 else 0 end) as low_line_count from orders, lineitem where o_orderkey = l_orderkey and l_shipmode in ('MAIL', 'FOB', 'TRUCK', 'REG AIR') and l_commitdate < l_receiptdate and l_shipdate < l_commitdate and l_receiptdate >= date '1993-10-20' and l_receiptdate < DATE '1993-10-20' + INTERVAL 5 YEAR group by l_shipmode order by l_shipmode;
select sum(l_extendedprice * (1 - l_discount)) as revenue from lineitem, part where ( p_partkey = l_partkey and p_brand = 'Brand#35' and p_container in ('LG DRUM', 'LG BOX', 'MED PACK', 'SM PACK') and l_quantity >= 11 and l_quantity <= 19 and p_size between 1 and 6 and l_shipmode in ('AIR', 'AIR REG') and l_shipinstruct = 'DELIVER IN PERSON' ) or ( p_partkey = l_partkey and p_brand = 'Brand#24' and p_container in ('JUMBO CAN', 'MED CAN', 'JUMBO DRUM', 'LG JAR') and l_quantity >= 15 and l_quantity <= 26 and p_size between 1 and 13 and l_shipmode in ('AIR', 'AIR REG') and l_shipinstruct = 'DELIVER IN PERSON' ) or ( p_partkey = l_partkey and p_brand = 'Brand#42' and p_container in ('LG DRUM', 'SM PKG', 'SM BAG', 'LG BAG') and l_quantity >= 23 and l_quantity <= 31 and p_size between 1 and 19 and l_shipmode in ('AIR', 'AIR REG') and l_shipinstruct = 'DELIVER IN PERSON' );
select l_shipmode, sum(case when o_orderpriority = '1-URGENT' or o_orderpriority = '2-HIGH' then 1 else 0 end) as high_line_count, sum(case when o_orderpriority <> '1-URGENT' and o_orderpriority <> '2-HIGH' then 1 else 0 end) as low_line_count from orders, lineitem where o_orderkey = l_orderkey and l_shipmode in ('REG AIR', 'RAIL', 'SHIP', 'TRUCK') and l_commitdate < l_receiptdate and l_shipdate < l_commitdate and l_receiptdate >= date '1997-08-14' and l_receiptdate < DATE '1997-08-14' + INTERVAL 4 YEAR group by l_shipmode order by l_shipmode;
select supp_nation, cust_nation, l_year, sum(volume) as revenue from ( select n1.n_name as supp_nation, n2.n_name as cust_nation, extract(year from l_shipdate) as l_year, l_extendedprice * (1 - l_discount) as volume from supplier, lineitem, orders, customer, nation n1, nation n2 where s_suppkey = l_suppkey and o_orderkey = l_orderkey and c_custkey = o_custkey and s_nationkey = n1.n_nationkey and c_nationkey = n2.n_nationkey and ((n1.n_name = 'EGYPT' and n2.n_name = 'MOROCCO') or (n1.n_name = 'BRAZIL' and n2.n_name = 'MOROCCO')) and l_shipdate between date '1993-01-01' and date '1996-12-31' ) as shipping group by supp_nation, cust_nation, l_year order by supp_nation, cust_nation, l_year;
select ps_partkey, sum(ps_supplycost * ps_availqty) as value from partsupp, supplier, nation where ps_suppkey = s_suppkey and s_nationkey = n_nationkey and (n_name = 'ALGERIA') group by ps_partkey having sum(ps_supplycost * ps_availqty) > ( select sum(ps_supplycost * ps_availqty) * 0.0000019946 from partsupp, supplier, nation where ps_suppkey = s_suppkey and s_nationkey = n_nationkey and (n_name = 'ALGERIA') ) order by value desc;
select sum(l_extendedprice * (1 - l_discount)) as revenue from lineitem, part where ( p_partkey = l_partkey and p_brand = 'Brand#35' and p_container in ('JUMBO CAN', 'SM BOX', 'LG BAG', 'MED PACK', 'WRAP DRUM', 'SM BAG', 'LG DRUM', 'SM PKG') and l_quantity >= 5 and l_quantity <= 16 and p_size between 1 and 5 and l_shipmode in ('AIR', 'AIR REG') and l_shipinstruct = 'DELIVER IN PERSON' ) or ( p_partkey = l_partkey and p_brand = 'Brand#24' and p_container in ('LG PACK', 'JUMBO CASE', 'MED PKG', 'MED CAN', 'MED CASE', 'JUMBO BAG', 'JUMBO CAN', 'LG CASE') and l_quantity >= 22 and l_quantity <= 33 and p_size between 1 and 12 and l_shipmode in ('AIR', 'AIR REG') and l_shipinstruct = 'DELIVER IN PERSON' ) or ( p_partkey = l_partkey and p_brand = 'Brand#42' and p_container in ('SM BAG', 'SM BOX', 'WRAP CAN', 'SM CASE', 'SM CAN', 'MED JAR', 'LG JAR', 'WRAP PKG') and l_quantity >= 34 and l_quantity <= 45 and p_size between 1 and 19 and l_shipmode in ('AIR', 'AIR REG') and l_shipinstruct = 'DELIVER IN PERSON' );
select s_acctbal, s_name, n_name, p_partkey, p_mfgr, s_address, s_phone, s_comment from part, supplier, partsupp, nation, region where p_partkey = ps_partkey and s_suppkey = ps_suppkey and p_size >= 47 and p_size <= 48 and (p_type like '%COPPER') and s_nationkey = n_nationkey and n_regionkey = r_regionkey and (r_name = 'AMERICA') and ps_supplycost = ( select min(ps_supplycost) from partsupp, supplier, nation, region where p_partkey = ps_partkey and s_suppkey = ps_suppkey and s_nationkey = n_nationkey and n_regionkey = r_regionkey and (r_name = 'AMERICA') ) order by s_acctbal desc, n_name, s_name, p_partkey LIMIT 100;
select l_returnflag, l_linestatus, sum(l_quantity) as sum_qty, sum(l_extendedprice) as sum_base_price, sum(l_extendedprice * (1 - l_discount)) as sum_disc_price, sum(l_extendedprice * (1 - l_discount) * (1 + l_tax)) as sum_charge, avg(l_quantity) as avg_qty, avg(l_extendedprice) as avg_price, avg(l_discount) as avg_disc, count(*) as count_order from lineitem where l_shipdate <= DATE '1994-08-31' - INTERVAL 99 DAY group by l_returnflag, l_linestatus order by l_returnflag, l_linestatus;
select sum(l_extendedprice) / 7.0 as avg_yearly from lineitem, part where p_partkey = l_partkey and p_brand = 'Brand#24' and (p_container = 'WRAP CAN' or p_container = 'JUMBO BAG') and l_quantity < ( select 0.2 * avg(l_quantity) from lineitem where l_partkey = p_partkey );
select sum(l_extendedprice * l_discount) as revenue from lineitem where l_shipdate >= date '1992-09-11' and l_shipdate < DATE '1992-09-11' + INTERVAL 5 YEAR and l_discount between 0.06 - 0.01 and 0.06 + 0.01 and l_quantity < 26;
select supp_nation, cust_nation, l_year, sum(volume) as revenue from ( select n1.n_name as supp_nation, n2.n_name as cust_nation, extract(year from l_shipdate) as l_year, l_extendedprice * (1 - l_discount) as volume from supplier, lineitem, orders, customer, nation n1, nation n2 where s_suppkey = l_suppkey and o_orderkey = l_orderkey and c_custkey = o_custkey and s_nationkey = n1.n_nationkey and c_nationkey = n2.n_nationkey and ((n1.n_name = 'CHINA' and n2.n_name = 'JORDAN') or (n1.n_name = 'CHINA' and n2.n_name = 'MOROCCO')) and l_shipdate between date '1993-01-01' and date '1995-12-31' ) as shipping group by supp_nation, cust_nation, l_year order by supp_nation, cust_nation, l_year;
select sum(l_extendedprice * (1 - l_discount)) as revenue from lineitem, part where ( p_partkey = l_partkey and p_brand = 'Brand#35' and p_container in ('SM JAR', 'MED PACK', 'JUMBO DRUM', 'MED PKG', 'MED JAR', 'LG CASE') and l_quantity >= 7 and l_quantity <= 16 and p_size between 1 and 5 and l_shipmode in ('AIR', 'AIR REG') and l_shipinstruct = 'DELIVER IN PERSON' ) or ( p_partkey = l_partkey and p_brand = 'Brand#24' and p_container in ('MED PACK', 'WRAP PACK', 'LG BOX', 'MED BAG', 'JUMBO BOX', 'SM PACK') and l_quantity >= 16 and l_quantity <= 24 and p_size between 1 and 13 and l_shipmode in ('AIR', 'AIR REG') and l_shipinstruct = 'DELIVER IN PERSON' ) or ( p_partkey = l_partkey and p_brand = 'Brand#42' and p_container in ('MED PACK', 'MED JAR', 'LG CAN', 'WRAP JAR', 'SM CASE', 'MED DRUM') and l_quantity >= 24 and l_quantity <= 35 and p_size between 1 and 10 and l_shipmode in ('AIR', 'AIR REG') and l_shipinstruct = 'DELIVER IN PERSON' );
select 100.00 * sum(case when p_type like 'PROMO%' then l_extendedprice * (1 - l_discount) else 0 end) / sum(l_extendedprice * (1 - l_discount)) as promo_revenue from lineitem, part where l_partkey = p_partkey and l_shipdate >= date '1992-12-29' and l_shipdate < DATE '1992-12-29' + INTERVAL 10 MONTH;
select supp_nation, cust_nation, l_year, sum(volume) as revenue from ( select n1.n_name as supp_nation, n2.n_name as cust_nation, extract(year from l_shipdate) as l_year, l_extendedprice * (1 - l_discount) as volume from supplier, lineitem, orders, customer, nation n1, nation n2 where s_suppkey = l_suppkey and o_orderkey = l_orderkey and c_custkey = o_custkey and s_nationkey = n1.n_nationkey and c_nationkey = n2.n_nationkey and ((n1.n_name = 'PERU' and n2.n_name = 'FRANCE') or (n1.n_name = 'ETHIOPIA' and n2.n_name = 'FRANCE')) and l_shipdate between date '1994-01-01' and date '1994-12-31' ) as shipping group by supp_nation, cust_nation, l_year order by supp_nation, cust_nation, l_year;
select c_count, count(*) as custdist from ( select c_custkey, count(o_orderkey) as c_count from customer left outer join orders on c_custkey = o_custkey and o_comment not like '%unusual%accounts%' and o_comment not like '%special%packages%' and o_comment not like '%express%accounts%' group by c_custkey ) as c_orders group by c_count order by custdist desc, c_count desc;
select ps_partkey, sum(ps_supplycost * ps_availqty) as value from partsupp, supplier, nation where ps_suppkey = s_suppkey and s_nationkey = n_nationkey and (n_name = 'MOROCCO' or n_name = 'JORDAN') group by ps_partkey having sum(ps_supplycost * ps_availqty) > ( select sum(ps_supplycost * ps_availqty) * 0.0000009943 from partsupp, supplier, nation where ps_suppkey = s_suppkey and s_nationkey = n_nationkey and (n_name = 'MOROCCO' or n_name = 'JORDAN') ) order by value desc;
select sum(l_extendedprice) / 7.0 as avg_yearly from lineitem, part where p_partkey = l_partkey and p_brand = 'Brand#24' and (p_container = 'SM BOX' or p_container = 'JUMBO JAR' or p_container = 'WRAP CAN') and l_quantity < ( select 0.2 * avg(l_quantity) from lineitem where l_partkey = p_partkey );
select ps_partkey, sum(ps_supplycost * ps_availqty) as value from partsupp, supplier, nation where ps_suppkey = s_suppkey and s_nationkey = n_nationkey and (n_name = 'VIETNAM') group by ps_partkey having sum(ps_supplycost * ps_availqty) > ( select sum(ps_supplycost * ps_availqty) * 0.0000004523 from partsupp, supplier, nation where ps_suppkey = s_suppkey and s_nationkey = n_nationkey and (n_name = 'VIETNAM') ) order by value desc;
select l_shipmode, sum(case when o_orderpriority = '1-URGENT' or o_orderpriority = '2-HIGH' then 1 else 0 end) as high_line_count, sum(case when o_orderpriority <> '1-URGENT' and o_orderpriority <> '2-HIGH' then 1 else 0 end) as low_line_count from orders, lineitem where o_orderkey = l_orderkey and l_shipmode in ('SHIP', 'MAIL', 'TRUCK', 'FOB') and l_commitdate < l_receiptdate and l_shipdate < l_commitdate and l_receiptdate >= date '1998-02-07' and l_receiptdate < DATE '1998-02-07' + INTERVAL 2 YEAR group by l_shipmode order by l_shipmode;
select sum(l_extendedprice * l_discount) as revenue from lineitem where l_shipdate >= date '1992-03-22' and l_shipdate < DATE '1992-03-22' + INTERVAL 4 YEAR and l_discount between 0.06 - 0.03 and 0.06 + 0.03 and l_quantity < 23;
select o_orderpriority, count(*) as order_count from orders where o_orderdate >= date '1995-12-01' and o_orderdate < DATE '1995-12-01' + INTERVAL 12 MONTH and exists ( select * from lineitem where l_orderkey = o_orderkey and l_commitdate < l_receiptdate ) group by o_orderpriority order by o_orderpriority;
select 100.00 * sum(case when p_type like 'PROMO%' then l_extendedprice * (1 - l_discount) else 0 end) / sum(l_extendedprice * (1 - l_discount)) as promo_revenue from lineitem, part where l_partkey = p_partkey and l_shipdate >= date '1992-01-06' and l_shipdate < DATE '1992-01-06' + INTERVAL 41 MONTH;
select s_name, s_address from supplier, nation where s_suppkey in ( select ps_suppkey from partsupp where ps_partkey in ( select p_partkey from part where (p_name like '%grey%' or p_name like '%pink%') ) and ps_availqty > ( select 0.5 * sum(l_quantity) from lineitem where l_partkey = ps_partkey and l_suppkey = ps_suppkey and l_shipdate >= date '1994-04-23' and l_shipdate < DATE '1994-04-23' + INTERVAL 3 YEAR ) ) and s_nationkey = n_nationkey and n_name = 'CHINA' order by s_name;
select sum(l_extendedprice) / 7.0 as avg_yearly from lineitem, part where p_partkey = l_partkey and p_brand = 'Brand#24' and (p_container = 'LG BAG' or p_container = 'LG BOX') and l_quantity < ( select 0.2 * avg(l_quantity) from lineitem where l_partkey = p_partkey );
select c_count, count(*) as custdist from ( select c_custkey, count(o_orderkey) as c_count from customer left outer join orders on c_custkey = o_custkey and o_comment not like '%unusual%deposits%' group by c_custkey ) as c_orders group by c_count order by custdist desc, c_count desc;
select l_returnflag, l_linestatus, sum(l_quantity) as sum_qty, sum(l_extendedprice) as sum_base_price, sum(l_extendedprice * (1 - l_discount)) as sum_disc_price, sum(l_extendedprice * (1 - l_discount) * (1 + l_tax)) as sum_charge, avg(l_quantity) as avg_qty, avg(l_extendedprice) as avg_price, avg(l_discount) as avg_disc, count(*) as count_order from lineitem where l_shipdate <= DATE '1996-07-19' - INTERVAL 99 DAY group by l_returnflag, l_linestatus order by l_returnflag, l_linestatus;
select ps_partkey, sum(ps_supplycost * ps_availqty) as value from partsupp, supplier, nation where ps_suppkey = s_suppkey and s_nationkey = n_nationkey and (n_name = 'PERU' or n_name = 'UNITED STATES') group by ps_partkey having sum(ps_supplycost * ps_availqty) > ( select sum(ps_supplycost * ps_availqty) * 0.0000002292 from partsupp, supplier, nation where ps_suppkey = s_suppkey and s_nationkey = n_nationkey and (n_name = 'PERU' or n_name = 'UNITED STATES') ) order by value desc;
select s_acctbal, s_name, n_name, p_partkey, p_mfgr, s_address, s_phone, s_comment from part, supplier, partsupp, nation, region where p_partkey = ps_partkey and s_suppkey = ps_suppkey and p_size = 33 and (p_type like '%NICKEL') and s_nationkey = n_nationkey and n_regionkey = r_regionkey and (r_name = 'AFRICA' or r_name = 'EUROPE' or r_name = 'MIDDLE EAST') and ps_supplycost = ( select min(ps_supplycost) from partsupp, supplier, nation, region where p_partkey = ps_partkey and s_suppkey = ps_suppkey and s_nationkey = n_nationkey and n_regionkey = r_regionkey and (r_name = 'AFRICA' or r_name = 'EUROPE' or r_name = 'MIDDLE EAST') ) order by s_acctbal desc, n_name, s_name, p_partkey LIMIT 100;
select ps_partkey, sum(ps_supplycost * ps_availqty) as value from partsupp, supplier, nation where ps_suppkey = s_suppkey and s_nationkey = n_nationkey and (n_name = 'SAUDI ARABIA' or n_name = 'FRANCE') group by ps_partkey having sum(ps_supplycost * ps_availqty) > ( select sum(ps_supplycost * ps_availqty) * 0.0000021528 from partsupp, supplier, nation where ps_suppkey = s_suppkey and s_nationkey = n_nationkey and (n_name = 'SAUDI ARABIA' or n_name = 'FRANCE') ) order by value desc;
select supp_nation, cust_nation, l_year, sum(volume) as revenue from ( select n1.n_name as supp_nation, n2.n_name as cust_nation, extract(year from l_shipdate) as l_year, l_extendedprice * (1 - l_discount) as volume from supplier, lineitem, orders, customer, nation n1, nation n2 where s_suppkey = l_suppkey and o_orderkey = l_orderkey and c_custkey = o_custkey and s_nationkey = n1.n_nationkey and c_nationkey = n2.n_nationkey and ((n1.n_name = 'RUSSIA' and n2.n_name = 'VIETNAM') or (n1.n_name = 'VIETNAM' and n2.n_name = 'RUSSIA')) and l_shipdate between date '1993-01-01' and date '1993-12-31' ) as shipping group by supp_nation, cust_nation, l_year order by supp_nation, cust_nation, l_year;
select sum(l_extendedprice) / 7.0 as avg_yearly from lineitem, part where p_partkey = l_partkey and p_brand = 'Brand#24' and (p_container = 'MED CAN') and l_quantity < ( select 0.2 * avg(l_quantity) from lineitem where l_partkey = p_partkey );
select s_acctbal, s_name, n_name, p_partkey, p_mfgr, s_address, s_phone, s_comment from part, supplier, partsupp, nation, region where p_partkey = ps_partkey and s_suppkey = ps_suppkey and p_size = 7 and (p_type like '%TIN' or p_type like '%NICKEL' or p_type like '%BRASS') and s_nationkey = n_nationkey and n_regionkey = r_regionkey and (r_name = 'ASIA') and ps_supplycost = ( select min(ps_supplycost) from partsupp, supplier, nation, region where p_partkey = ps_partkey and s_suppkey = ps_suppkey and s_nationkey = n_nationkey and n_regionkey = r_regionkey and (r_name = 'ASIA') ) order by s_acctbal desc, n_name, s_name, p_partkey LIMIT 100;
select ps_partkey, sum(ps_supplycost * ps_availqty) as value from partsupp, supplier, nation where ps_suppkey = s_suppkey and s_nationkey = n_nationkey and (n_name = 'GERMANY' or n_name = 'ETHIOPIA' or n_name = 'ARGENTINA') group by ps_partkey having sum(ps_supplycost * ps_availqty) > ( select sum(ps_supplycost * ps_availqty) * 0.0000018829 from partsupp, supplier, nation where ps_suppkey = s_suppkey and s_nationkey = n_nationkey and (n_name = 'GERMANY' or n_name = 'ETHIOPIA' or n_name = 'ARGENTINA') ) order by value desc;
select sum(l_extendedprice * l_discount) as revenue from lineitem where l_shipdate >= date '1996-09-03' and l_shipdate < DATE '1996-09-03' + INTERVAL 3 YEAR and l_discount between 0.04 - 0.02 and 0.04 + 0.02 and l_quantity < 12;
select s_acctbal, s_name, n_name, p_partkey, p_mfgr, s_address, s_phone, s_comment from part, supplier, partsupp, nation, region where p_partkey = ps_partkey and s_suppkey = ps_suppkey and p_size = 42 and (p_type like '%TIN' or p_type like '%NICKEL' or p_type like '%COPPER') and s_nationkey = n_nationkey and n_regionkey = r_regionkey and (r_name = 'EUROPE') and ps_supplycost = ( select min(ps_supplycost) from partsupp, supplier, nation, region where p_partkey = ps_partkey and s_suppkey = ps_suppkey and s_nationkey = n_nationkey and n_regionkey = r_regionkey and (r_name = 'EUROPE') ) order by s_acctbal desc, n_name, s_name, p_partkey LIMIT 100;
select sum(l_extendedprice) / 7.0 as avg_yearly from lineitem, part where p_partkey = l_partkey and p_brand = 'Brand#24' and (p_container = 'JUMBO BAG') and l_quantity < ( select 0.2 * avg(l_quantity) from lineitem where l_partkey = p_partkey );
select s_name, s_address from supplier, nation where s_suppkey in ( select ps_suppkey from partsupp where ps_partkey in ( select p_partkey from part where (p_name like '%grey%' or p_name like '%red%' or p_name like '%lavender%') ) and ps_availqty > ( select 0.5 * sum(l_quantity) from lineitem where l_partkey = ps_partkey and l_suppkey = ps_suppkey and l_shipdate >= date '1994-05-13' and l_shipdate < DATE '1994-05-13' + INTERVAL 5 YEAR ) ) and s_nationkey = n_nationkey and n_name = 'CHINA' order by s_name;
select s_name, s_address from supplier, nation where s_suppkey in ( select ps_suppkey from partsupp where ps_partkey in ( select p_partkey from part where (p_name like '%orange%') ) and ps_availqty > ( select 0.5 * sum(l_quantity) from lineitem where l_partkey = ps_partkey and l_suppkey = ps_suppkey and l_shipdate >= date '1994-07-25' and l_shipdate < DATE '1994-07-25' + INTERVAL 3 YEAR ) ) and s_nationkey = n_nationkey and n_name = 'CHINA' order by s_name;
select supp_nation, cust_nation, l_year, sum(volume) as revenue from ( select n1.n_name as supp_nation, n2.n_name as cust_nation, extract(year from l_shipdate) as l_year, l_extendedprice * (1 - l_discount) as volume from supplier, lineitem, orders, customer, nation n1, nation n2 where s_suppkey = l_suppkey and o_orderkey = l_orderkey and c_custkey = o_custkey and s_nationkey = n1.n_nationkey and c_nationkey = n2.n_nationkey and ((n1.n_name = 'BRAZIL' and n2.n_name = 'IRAN') or (n1.n_name = 'BRAZIL' and n2.n_name = 'GERMANY')) and l_shipdate between date '1996-01-01' and date '1997-12-31' ) as shipping group by supp_nation, cust_nation, l_year order by supp_nation, cust_nation, l_year;
select s_name, s_address from supplier, nation where s_suppkey in ( select ps_suppkey from partsupp where ps_partkey in ( select p_partkey from part where (p_name like '%yellow%') ) and ps_availqty > ( select 0.5 * sum(l_quantity) from lineitem where l_partkey = ps_partkey and l_suppkey = ps_suppkey and l_shipdate >= date '1994-06-30' and l_shipdate < DATE '1994-06-30' + INTERVAL 1 YEAR ) ) and s_nationkey = n_nationkey and n_name = 'CHINA' order by s_name;
select s_acctbal, s_name, n_name, p_partkey, p_mfgr, s_address, s_phone, s_comment from part, supplier, partsupp, nation, region where p_partkey = ps_partkey and s_suppkey = ps_suppkey and p_size = 7 and (p_type like '%COPPER' or p_type like '%TIN') and s_nationkey = n_nationkey and n_regionkey = r_regionkey and (r_name = 'AMERICA') and ps_supplycost = ( select min(ps_supplycost) from partsupp, supplier, nation, region where p_partkey = ps_partkey and s_suppkey = ps_suppkey and s_nationkey = n_nationkey and n_regionkey = r_regionkey and (r_name = 'AMERICA') ) order by s_acctbal desc, n_name, s_name, p_partkey LIMIT 100;
select sum(l_extendedprice * l_discount) as revenue from lineitem where l_shipdate >= date '1993-10-30' and l_shipdate < DATE '1993-10-30' + INTERVAL 1 YEAR and l_discount between 0.02 - 0.03 and 0.02 + 0.03 and l_quantity < 15;
select supp_nation, cust_nation, l_year, sum(volume) as revenue from ( select n1.n_name as supp_nation, n2.n_name as cust_nation, extract(year from l_shipdate) as l_year, l_extendedprice * (1 - l_discount) as volume from supplier, lineitem, orders, customer, nation n1, nation n2 where s_suppkey = l_suppkey and o_orderkey = l_orderkey and c_custkey = o_custkey and s_nationkey = n1.n_nationkey and c_nationkey = n2.n_nationkey and ((n1.n_name = 'JAPAN' and n2.n_name = 'ROMANIA') or (n1.n_name = 'EGYPT' and n2.n_name = 'ROMANIA')) and l_shipdate between date '1994-01-01' and date '1997-12-31' ) as shipping group by supp_nation, cust_nation, l_year order by supp_nation, cust_nation, l_year;
select c_name, c_custkey, o_orderkey, o_orderdate, o_totalprice, sum(l_quantity) from customer, orders, lineitem where o_orderkey in ( select l_orderkey from lineitem group by l_orderkey having sum(l_quantity) > 141 ) and c_custkey = o_custkey and o_orderkey = l_orderkey group by c_name, c_custkey, o_orderkey, o_orderdate, o_totalprice order by o_totalprice desc, o_orderdate LIMIT 100;
select sum(l_extendedprice * l_discount) as revenue from lineitem where l_shipdate >= date '1992-05-13' and l_shipdate < DATE '1992-05-13' + INTERVAL 5 YEAR and l_discount between 0.05 - 0.01 and 0.05 + 0.01 and l_quantity < 30;
select s_acctbal, s_name, n_name, p_partkey, p_mfgr, s_address, s_phone, s_comment from part, supplier, partsupp, nation, region where p_partkey = ps_partkey and s_suppkey = ps_suppkey and p_size >= 17 and p_size <= 24 and (p_type like '%NICKEL') and s_nationkey = n_nationkey and n_regionkey = r_regionkey and (r_name = 'ASIA') and ps_supplycost = ( select min(ps_supplycost) from partsupp, supplier, nation, region where p_partkey = ps_partkey and s_suppkey = ps_suppkey and s_nationkey = n_nationkey and n_regionkey = r_regionkey and (r_name = 'ASIA') ) order by s_acctbal desc, n_name, s_name, p_partkey LIMIT 100;
select p_brand, p_type, p_size, count(distinct ps_suppkey) as supplier_cnt from partsupp, part where p_partkey = ps_partkey and p_brand <> 'Brand#52' and p_type not like 'LARGE POLISHED%' and p_type not like 'SMALL BURNISHED%' and p_size in (1, 24, 39, 22, 48, 26, 27, 9) and ps_suppkey not in ( select s_suppkey from supplier where (s_comment like '%Customer%Issues%' or s_comment like '%Customer%Returns%' or s_comment like '%Customer%Dislikes%') ) group by p_brand, p_type, p_size order by supplier_cnt desc, p_brand, p_type, p_size;
select supp_nation, cust_nation, l_year, sum(volume) as revenue from ( select n1.n_name as supp_nation, n2.n_name as cust_nation, extract(year from l_shipdate) as l_year, l_extendedprice * (1 - l_discount) as volume from supplier, lineitem, orders, customer, nation n1, nation n2 where s_suppkey = l_suppkey and o_orderkey = l_orderkey and c_custkey = o_custkey and s_nationkey = n1.n_nationkey and c_nationkey = n2.n_nationkey and ((n1.n_name = 'UNITED STATES' and n2.n_name = 'FRANCE') or (n1.n_name = 'UNITED KINGDOM' and n2.n_name = 'FRANCE')) and l_shipdate between date '1996-01-01' and date '1996-12-31' ) as shipping group by supp_nation, cust_nation, l_year order by supp_nation, cust_nation, l_year;
select l_shipmode, sum(case when o_orderpriority = '1-URGENT' or o_orderpriority = '2-HIGH' then 1 else 0 end) as high_line_count, sum(case when o_orderpriority <> '1-URGENT' and o_orderpriority <> '2-HIGH' then 1 else 0 end) as low_line_count from orders, lineitem where o_orderkey = l_orderkey and l_shipmode in ('SHIP', 'RAIL', 'FOB', 'REG AIR') and l_commitdate < l_receiptdate and l_shipdate < l_commitdate and l_receiptdate >= date '1995-02-11' and l_receiptdate < DATE '1995-02-11' + INTERVAL 2 YEAR group by l_shipmode order by l_shipmode;
select l_returnflag, l_linestatus, sum(l_quantity) as sum_qty, sum(l_extendedprice) as sum_base_price, sum(l_extendedprice * (1 - l_discount)) as sum_disc_price, sum(l_extendedprice * (1 - l_discount) * (1 + l_tax)) as sum_charge, avg(l_quantity) as avg_qty, avg(l_extendedprice) as avg_price, avg(l_discount) as avg_disc, count(*) as count_order from lineitem where l_shipdate <= DATE '1994-03-23' - INTERVAL 99 DAY group by l_returnflag, l_linestatus order by l_returnflag, l_linestatus;
select o_orderpriority, count(*) as order_count from orders where o_orderdate >= date '1995-12-01' and o_orderdate < DATE '1995-12-01' + INTERVAL 4 MONTH and exists ( select * from lineitem where l_orderkey = o_orderkey and l_commitdate < l_receiptdate ) group by o_orderpriority order by o_orderpriority;
select sum(l_extendedprice * (1 - l_discount)) as revenue from lineitem, part where ( p_partkey = l_partkey and p_brand = 'Brand#35' and p_container in ('LG JAR', 'SM PACK', 'JUMBO PKG', 'WRAP CAN', 'JUMBO PACK', 'SM JAR') and l_quantity >= 9 and l_quantity <= 16 and p_size between 1 and 8 and l_shipmode in ('AIR', 'AIR REG') and l_shipinstruct = 'DELIVER IN PERSON' ) or ( p_partkey = l_partkey and p_brand = 'Brand#24' and p_container in ('LG DRUM', 'MED CASE', 'MED BOX', 'WRAP BAG', 'MED BAG', 'JUMBO CASE') and l_quantity >= 19 and l_quantity <= 24 and p_size between 1 and 7 and l_shipmode in ('AIR', 'AIR REG') and l_shipinstruct = 'DELIVER IN PERSON' ) or ( p_partkey = l_partkey and p_brand = 'Brand#42' and p_container in ('SM BOX', 'JUMBO BOX', 'SM DRUM', 'MED DRUM', 'SM BAG', 'SM PACK') and l_quantity >= 33 and l_quantity <= 45 and p_size between 1 and 22 and l_shipmode in ('AIR', 'AIR REG') and l_shipinstruct = 'DELIVER IN PERSON' );
select ps_partkey, sum(ps_supplycost * ps_availqty) as value from partsupp, supplier, nation where ps_suppkey = s_suppkey and s_nationkey = n_nationkey and (n_name = 'ROMANIA' or n_name = 'FRANCE' or n_name = 'MOZAMBIQUE') group by ps_partkey having sum(ps_supplycost * ps_availqty) > ( select sum(ps_supplycost * ps_availqty) * 0.0000013184 from partsupp, supplier, nation where ps_suppkey = s_suppkey and s_nationkey = n_nationkey and (n_name = 'ROMANIA' or n_name = 'FRANCE' or n_name = 'MOZAMBIQUE') ) order by value desc;
select s_acctbal, s_name, n_name, p_partkey, p_mfgr, s_address, s_phone, s_comment from part, supplier, partsupp, nation, region where p_partkey = ps_partkey and s_suppkey = ps_suppkey and p_size = 7 and (p_type like '%BRASS') and s_nationkey = n_nationkey and n_regionkey = r_regionkey and (r_name = 'ASIA' or r_name = 'AFRICA') and ps_supplycost = ( select min(ps_supplycost) from partsupp, supplier, nation, region where p_partkey = ps_partkey and s_suppkey = ps_suppkey and s_nationkey = n_nationkey and n_regionkey = r_regionkey and (r_name = 'ASIA' or r_name = 'AFRICA') ) order by s_acctbal desc, n_name, s_name, p_partkey LIMIT 100;
select nation, o_year, sum(amount) as sum_profit from ( select n_name as nation, extract(year from o_orderdate) as o_year, l_extendedprice * (1 - l_discount) - ps_supplycost * l_quantity as amount from part, supplier, lineitem, partsupp, orders, nation where s_suppkey = l_suppkey and ps_suppkey = l_suppkey and ps_partkey = l_partkey and p_partkey = l_partkey and o_orderkey = l_orderkey and s_nationkey = n_nationkey and p_name like '%yellow%' ) as profit group by nation, o_year order by nation, o_year desc;
select sum(l_extendedprice * l_discount) as revenue from lineitem where l_shipdate >= date '1996-09-26' and l_shipdate < DATE '1996-09-26' + INTERVAL 2 YEAR and l_discount between 0.08 - 0.01 and 0.08 + 0.01 and l_quantity < 11;
select o_orderpriority, count(*) as order_count from orders where o_orderdate >= date '1995-12-01' and o_orderdate < DATE '1995-12-01' + INTERVAL 31 MONTH and exists ( select * from lineitem where l_orderkey = o_orderkey and l_commitdate < l_receiptdate ) group by o_orderpriority order by o_orderpriority;
select s_acctbal, s_name, n_name, p_partkey, p_mfgr, s_address, s_phone, s_comment from part, supplier, partsupp, nation, region where p_partkey = ps_partkey and s_suppkey = ps_suppkey and p_size = 33 and (p_type like '%BRASS') and s_nationkey = n_nationkey and n_regionkey = r_regionkey and (r_name = 'EUROPE') and ps_supplycost = ( select min(ps_supplycost) from partsupp, supplier, nation, region where p_partkey = ps_partkey and s_suppkey = ps_suppkey and s_nationkey = n_nationkey and n_regionkey = r_regionkey and (r_name = 'EUROPE') ) order by s_acctbal desc, n_name, s_name, p_partkey LIMIT 100;
select s_acctbal, s_name, n_name, p_partkey, p_mfgr, s_address, s_phone, s_comment from part, supplier, partsupp, nation, region where p_partkey = ps_partkey and s_suppkey = ps_suppkey and p_size >= 29 and p_size <= 30 and (p_type like '%COPPER') and s_nationkey = n_nationkey and n_regionkey = r_regionkey and (r_name = 'EUROPE') and ps_supplycost = ( select min(ps_supplycost) from partsupp, supplier, nation, region where p_partkey = ps_partkey and s_suppkey = ps_suppkey and s_nationkey = n_nationkey and n_regionkey = r_regionkey and (r_name = 'EUROPE') ) order by s_acctbal desc, n_name, s_name, p_partkey LIMIT 100;
select sum(l_extendedprice * l_discount) as revenue from lineitem where l_shipdate >= date '1996-04-30' and l_shipdate < DATE '1996-04-30' + INTERVAL 5 YEAR and l_discount between 0.07 - 0.02 and 0.07 + 0.02 and l_quantity < 12;
select c_name, c_custkey, o_orderkey, o_orderdate, o_totalprice, sum(l_quantity) from customer, orders, lineitem where o_orderkey in ( select l_orderkey from lineitem group by l_orderkey having sum(l_quantity) > 171 ) and c_custkey = o_custkey and o_orderkey = l_orderkey group by c_name, c_custkey, o_orderkey, o_orderdate, o_totalprice order by o_totalprice desc, o_orderdate LIMIT 100;
select ps_partkey, sum(ps_supplycost * ps_availqty) as value from partsupp, supplier, nation where ps_suppkey = s_suppkey and s_nationkey = n_nationkey and (n_name = 'ALGERIA') group by ps_partkey having sum(ps_supplycost * ps_availqty) > ( select sum(ps_supplycost * ps_availqty) * 0.0000022971 from partsupp, supplier, nation where ps_suppkey = s_suppkey and s_nationkey = n_nationkey and (n_name = 'ALGERIA') ) order by value desc;
select c_name, c_custkey, o_orderkey, o_orderdate, o_totalprice, sum(l_quantity) from customer, orders, lineitem where o_orderkey in ( select l_orderkey from lineitem group by l_orderkey having sum(l_quantity) > 198 ) and c_custkey = o_custkey and o_orderkey = l_orderkey group by c_name, c_custkey, o_orderkey, o_orderdate, o_totalprice order by o_totalprice desc, o_orderdate LIMIT 100;
select sum(l_extendedprice * (1 - l_discount)) as revenue from lineitem, part where ( p_partkey = l_partkey and p_brand = 'Brand#35' and p_container in ('SM JAR', 'WRAP BAG', 'MED CASE', 'SM CASE', 'JUMBO CASE', 'LG BOX', 'JUMBO BOX', 'MED JAR') and l_quantity >= 11 and l_quantity <= 17 and p_size between 1 and 3 and l_shipmode in ('AIR', 'AIR REG') and l_shipinstruct = 'DELIVER IN PERSON' ) or ( p_partkey = l_partkey and p_brand = 'Brand#24' and p_container in ('LG BAG', 'JUMBO CASE', 'JUMBO JAR', 'SM PKG', 'SM DRUM', 'WRAP DRUM', 'MED CAN', 'JUMBO CAN') and l_quantity >= 18 and l_quantity <= 26 and p_size between 1 and 7 and l_shipmode in ('AIR', 'AIR REG') and l_shipinstruct = 'DELIVER IN PERSON' ) or ( p_partkey = l_partkey and p_brand = 'Brand#42' and p_container in ('WRAP DRUM', 'SM CASE', 'MED CASE', 'WRAP CASE', 'JUMBO PKG', 'JUMBO BOX', 'JUMBO CAN', 'MED BAG') and l_quantity >= 23 and l_quantity <= 29 and p_size between 1 and 15 and l_shipmode in ('AIR', 'AIR REG') and l_shipinstruct = 'DELIVER IN PERSON' );
select 100.00 * sum(case when p_type like 'PROMO%' then l_extendedprice * (1 - l_discount) else 0 end) / sum(l_extendedprice * (1 - l_discount)) as promo_revenue from lineitem, part where l_partkey = p_partkey and l_shipdate >= date '1993-09-10' and l_shipdate < DATE '1993-09-10' + INTERVAL 4 MONTH;
select 100.00 * sum(case when p_type like 'PROMO%' then l_extendedprice * (1 - l_discount) else 0 end) / sum(l_extendedprice * (1 - l_discount)) as promo_revenue from lineitem, part where l_partkey = p_partkey and l_shipdate >= date '1993-12-06' and l_shipdate < DATE '1993-12-06' + INTERVAL 20 MONTH;
select sum(l_extendedprice * l_discount) as revenue from lineitem where l_shipdate >= date '1993-04-21' and l_shipdate < DATE '1993-04-21' + INTERVAL 1 YEAR and l_discount between 0.03 - 0.02 and 0.03 + 0.02 and l_quantity < 13;
select p_brand, p_type, p_size, count(distinct ps_suppkey) as supplier_cnt from partsupp, part where p_partkey = ps_partkey and p_brand <> 'Brand#52' and p_type not like 'SMALL BURNISHED%' and p_type not like 'ECONOMY ANODIZED%' and p_type not like 'MEDIUM POLISHED%' and p_size in (31, 10, 43, 29, 8, 41, 7, 36) and ps_suppkey not in ( select s_suppkey from supplier where (s_comment like '%Customer%Complaints%' or s_comment like '%Customer%Problems%' or s_comment like '%Customer%Dislikes%') ) group by p_brand, p_type, p_size order by supplier_cnt desc, p_brand, p_type, p_size;
select l_returnflag, l_linestatus, sum(l_quantity) as sum_qty, sum(l_extendedprice) as sum_base_price, sum(l_extendedprice * (1 - l_discount)) as sum_disc_price, sum(l_extendedprice * (1 - l_discount) * (1 + l_tax)) as sum_charge, avg(l_quantity) as avg_qty, avg(l_extendedprice) as avg_price, avg(l_discount) as avg_disc, count(*) as count_order from lineitem where l_shipdate <= DATE '1998-05-29' - INTERVAL 99 DAY group by l_returnflag, l_linestatus order by l_returnflag, l_linestatus;
select sum(l_extendedprice * (1 - l_discount)) as revenue from lineitem, part where ( p_partkey = l_partkey and p_brand = 'Brand#35' and p_container in ('MED CAN', 'SM PACK', 'WRAP JAR', 'WRAP PACK', 'MED JAR') and l_quantity >= 10 and l_quantity <= 22 and p_size between 1 and 3 and l_shipmode in ('AIR', 'AIR REG') and l_shipinstruct = 'DELIVER IN PERSON' ) or ( p_partkey = l_partkey and p_brand = 'Brand#24' and p_container in ('LG CAN', 'MED PKG', 'SM CAN', 'MED JAR', 'WRAP JAR') and l_quantity >= 21 and l_quantity <= 32 and p_size between 1 and 10 and l_shipmode in ('AIR', 'AIR REG') and l_shipinstruct = 'DELIVER IN PERSON' ) or ( p_partkey = l_partkey and p_brand = 'Brand#42' and p_container in ('MED BAG', 'LG JAR', 'MED BOX', 'JUMBO PACK', 'WRAP DRUM') and l_quantity >= 24 and l_quantity <= 31 and p_size between 1 and 16 and l_shipmode in ('AIR', 'AIR REG') and l_shipinstruct = 'DELIVER IN PERSON' );
select o_orderpriority, count(*) as order_count from orders where o_orderdate >= date '1995-12-01' and o_orderdate < DATE '1995-12-01' + INTERVAL 7 MONTH and exists ( select * from lineitem where l_orderkey = o_orderkey and l_commitdate < l_receiptdate ) group by o_orderpriority order by o_orderpriority;
select c_count, count(*) as custdist from ( select c_custkey, count(o_orderkey) as c_count from customer left outer join orders on c_custkey = o_custkey and o_comment not like '%express%requests%' and o_comment not like '%unusual%deposits%' group by c_custkey ) as c_orders group by c_count order by custdist desc, c_count desc;
select supp_nation, cust_nation, l_year, sum(volume) as revenue from ( select n1.n_name as supp_nation, n2.n_name as cust_nation, extract(year from l_shipdate) as l_year, l_extendedprice * (1 - l_discount) as volume from supplier, lineitem, orders, customer, nation n1, nation n2 where s_suppkey = l_suppkey and o_orderkey = l_orderkey and c_custkey = o_custkey and s_nationkey = n1.n_nationkey and c_nationkey = n2.n_nationkey and ((n1.n_name = 'UNITED STATES' and n2.n_name = 'PERU') or (n1.n_name = 'PERU' and n2.n_name = 'UNITED STATES')) and l_shipdate between date '1996-01-01' and date '1997-12-31' ) as shipping group by supp_nation, cust_nation, l_year order by supp_nation, cust_nation, l_year;
select sum(l_extendedprice) / 7.0 as avg_yearly from lineitem, part where p_partkey = l_partkey and p_brand = 'Brand#24' and (p_container = 'MED CASE' or p_container = 'WRAP CASE') and l_quantity < ( select 0.2 * avg(l_quantity) from lineitem where l_partkey = p_partkey );
select sum(l_extendedprice * (1 - l_discount)) as revenue from lineitem, part where ( p_partkey = l_partkey and p_brand = 'Brand#35' and p_container in ('WRAP JAR', 'JUMBO BOX', 'SM CAN', 'SM JAR', 'WRAP DRUM', 'SM BAG', 'MED CAN', 'LG CAN') and l_quantity >= 10 and l_quantity <= 21 and p_size between 1 and 5 and l_shipmode in ('AIR', 'AIR REG') and l_shipinstruct = 'DELIVER IN PERSON' ) or ( p_partkey = l_partkey and p_brand = 'Brand#24' and p_container in ('SM BOX', 'LG CAN', 'LG CASE', 'JUMBO CASE', 'MED CASE', 'LG BAG', 'JUMBO BAG', 'JUMBO PKG') and l_quantity >= 18 and l_quantity <= 28 and p_size between 1 and 11 and l_shipmode in ('AIR', 'AIR REG') and l_shipinstruct = 'DELIVER IN PERSON' ) or ( p_partkey = l_partkey and p_brand = 'Brand#42' and p_container in ('MED PACK', 'WRAP BAG', 'WRAP JAR', 'WRAP DRUM', 'WRAP PKG', 'WRAP PACK', 'JUMBO JAR', 'SM CASE') and l_quantity >= 26 and l_quantity <= 34 and p_size between 1 and 19 and l_shipmode in ('AIR', 'AIR REG') and l_shipinstruct = 'DELIVER IN PERSON' );
select s_acctbal, s_name, n_name, p_partkey, p_mfgr, s_address, s_phone, s_comment from part, supplier, partsupp, nation, region where p_partkey = ps_partkey and s_suppkey = ps_suppkey and p_size = 18 and (p_type like '%STEEL' or p_type like '%NICKEL' or p_type like '%TIN') and s_nationkey = n_nationkey and n_regionkey = r_regionkey and (r_name = 'ASIA') and ps_supplycost = ( select min(ps_supplycost) from partsupp, supplier, nation, region where p_partkey = ps_partkey and s_suppkey = ps_suppkey and s_nationkey = n_nationkey and n_regionkey = r_regionkey and (r_name = 'ASIA') ) order by s_acctbal desc, n_name, s_name, p_partkey LIMIT 100;
select supp_nation, cust_nation, l_year, sum(volume) as revenue from ( select n1.n_name as supp_nation, n2.n_name as cust_nation, extract(year from l_shipdate) as l_year, l_extendedprice * (1 - l_discount) as volume from supplier, lineitem, orders, customer, nation n1, nation n2 where s_suppkey = l_suppkey and o_orderkey = l_orderkey and c_custkey = o_custkey and s_nationkey = n1.n_nationkey and c_nationkey = n2.n_nationkey and ((n1.n_name = 'CANADA' and n2.n_name = 'RUSSIA') or (n1.n_name = 'VIETNAM' and n2.n_name = 'RUSSIA')) and l_shipdate between date '1997-01-01' and date '1997-12-31' ) as shipping group by supp_nation, cust_nation, l_year order by supp_nation, cust_nation, l_year;
select s_acctbal, s_name, n_name, p_partkey, p_mfgr, s_address, s_phone, s_comment from part, supplier, partsupp, nation, region where p_partkey = ps_partkey and s_suppkey = ps_suppkey and p_size = 13 and (p_type like '%NICKEL' or p_type like '%COPPER' or p_type like '%BRASS') and s_nationkey = n_nationkey and n_regionkey = r_regionkey and (r_name = 'AFRICA') and ps_supplycost = ( select min(ps_supplycost) from partsupp, supplier, nation, region where p_partkey = ps_partkey and s_suppkey = ps_suppkey and s_nationkey = n_nationkey and n_regionkey = r_regionkey and (r_name = 'AFRICA') ) order by s_acctbal desc, n_name, s_name, p_partkey LIMIT 100;
select l_shipmode, sum(case when o_orderpriority = '1-URGENT' or o_orderpriority = '2-HIGH' then 1 else 0 end) as high_line_count, sum(case when o_orderpriority <> '1-URGENT' and o_orderpriority <> '2-HIGH' then 1 else 0 end) as low_line_count from orders, lineitem where o_orderkey = l_orderkey and l_shipmode in ('MAIL', 'FOB', 'SHIP') and l_commitdate < l_receiptdate and l_shipdate < l_commitdate and l_receiptdate >= date '1993-08-12' and l_receiptdate < DATE '1993-08-12' + INTERVAL 4 YEAR group by l_shipmode order by l_shipmode;
select l_shipmode, sum(case when o_orderpriority = '1-URGENT' or o_orderpriority = '2-HIGH' then 1 else 0 end) as high_line_count, sum(case when o_orderpriority <> '1-URGENT' and o_orderpriority <> '2-HIGH' then 1 else 0 end) as low_line_count from orders, lineitem where o_orderkey = l_orderkey and l_shipmode in ('RAIL', 'TRUCK') and l_commitdate < l_receiptdate and l_shipdate < l_commitdate and l_receiptdate >= date '1996-04-11' and l_receiptdate < DATE '1996-04-11' + INTERVAL 6 YEAR group by l_shipmode order by l_shipmode;
select sum(l_extendedprice) / 7.0 as avg_yearly from lineitem, part where p_partkey = l_partkey and p_brand = 'Brand#24' and (p_container = 'JUMBO PACK') and l_quantity < ( select 0.2 * avg(l_quantity) from lineitem where l_partkey = p_partkey );
select c_name, c_custkey, o_orderkey, o_orderdate, o_totalprice, sum(l_quantity) from customer, orders, lineitem where o_orderkey in ( select l_orderkey from lineitem group by l_orderkey having sum(l_quantity) > 299 ) and c_custkey = o_custkey and o_orderkey = l_orderkey group by c_name, c_custkey, o_orderkey, o_orderdate, o_totalprice order by o_totalprice desc, o_orderdate LIMIT 100;
select s_acctbal, s_name, n_name, p_partkey, p_mfgr, s_address, s_phone, s_comment from part, supplier, partsupp, nation, region where p_partkey = ps_partkey and s_suppkey = ps_suppkey and p_size = 40 and (p_type like '%STEEL') and s_nationkey = n_nationkey and n_regionkey = r_regionkey and (r_name = 'AMERICA') and ps_supplycost = ( select min(ps_supplycost) from partsupp, supplier, nation, region where p_partkey = ps_partkey and s_suppkey = ps_suppkey and s_nationkey = n_nationkey and n_regionkey = r_regionkey and (r_name = 'AMERICA') ) order by s_acctbal desc, n_name, s_name, p_partkey LIMIT 100;
select c_name, c_custkey, o_orderkey, o_orderdate, o_totalprice, sum(l_quantity) from customer, orders, lineitem where o_orderkey in ( select l_orderkey from lineitem group by l_orderkey having sum(l_quantity) > 269 ) and c_custkey = o_custkey and o_orderkey = l_orderkey group by c_name, c_custkey, o_orderkey, o_orderdate, o_totalprice order by o_totalprice desc, o_orderdate LIMIT 100;
select s_name, s_address from supplier, nation where s_suppkey in ( select ps_suppkey from partsupp where ps_partkey in ( select p_partkey from part where (p_name like '%blue%' or p_name like '%brown%' or p_name like '%purple%' or p_name like '%orange%') ) and ps_availqty > ( select 0.5 * sum(l_quantity) from lineitem where l_partkey = ps_partkey and l_suppkey = ps_suppkey and l_shipdate >= date '1994-03-17' and l_shipdate < DATE '1994-03-17' + INTERVAL 3 YEAR ) ) and s_nationkey = n_nationkey and n_name = 'CHINA' order by s_name;
select supp_nation, cust_nation, l_year, sum(volume) as revenue from ( select n1.n_name as supp_nation, n2.n_name as cust_nation, extract(year from l_shipdate) as l_year, l_extendedprice * (1 - l_discount) as volume from supplier, lineitem, orders, customer, nation n1, nation n2 where s_suppkey = l_suppkey and o_orderkey = l_orderkey and c_custkey = o_custkey and s_nationkey = n1.n_nationkey and c_nationkey = n2.n_nationkey and ((n1.n_name = 'EGYPT' and n2.n_name = 'KENYA') or (n1.n_name = 'EGYPT' and n2.n_name = 'ETHIOPIA')) and l_shipdate between date '1996-01-01' and date '1998-12-31' ) as shipping group by supp_nation, cust_nation, l_year order by supp_nation, cust_nation, l_year;
select c_count, count(*) as custdist from ( select c_custkey, count(o_orderkey) as c_count from customer left outer join orders on c_custkey = o_custkey and o_comment not like '%special%requests%' and o_comment not like '%pending%packages%' and o_comment not like '%unusual%deposits%' group by c_custkey ) as c_orders group by c_count order by custdist desc, c_count desc;
select sum(l_extendedprice * (1 - l_discount)) as revenue from lineitem, part where ( p_partkey = l_partkey and p_brand = 'Brand#35' and p_container in ('LG JAR', 'LG DRUM', 'JUMBO PKG', 'MED CAN', 'LG BAG', 'MED BAG', 'SM BOX') and l_quantity >= 8 and l_quantity <= 18 and p_size between 1 and 5 and l_shipmode in ('AIR', 'AIR REG') and l_shipinstruct = 'DELIVER IN PERSON' ) or ( p_partkey = l_partkey and p_brand = 'Brand#24' and p_container in ('MED CAN', 'JUMBO BOX', 'LG PACK', 'MED PACK', 'WRAP BOX', 'LG DRUM', 'SM DRUM') and l_quantity >= 21 and l_quantity <= 32 and p_size between 1 and 12 and l_shipmode in ('AIR', 'AIR REG') and l_shipinstruct = 'DELIVER IN PERSON' ) or ( p_partkey = l_partkey and p_brand = 'Brand#42' and p_container in ('WRAP DRUM', 'JUMBO CASE', 'MED PKG', 'JUMBO CAN', 'MED CASE', 'SM BAG', 'WRAP CASE') and l_quantity >= 27 and l_quantity <= 37 and p_size between 1 and 18 and l_shipmode in ('AIR', 'AIR REG') and l_shipinstruct = 'DELIVER IN PERSON' );
select ps_partkey, sum(ps_supplycost * ps_availqty) as value from partsupp, supplier, nation where ps_suppkey = s_suppkey and s_nationkey = n_nationkey and (n_name = 'KENYA' or n_name = 'PERU') group by ps_partkey having sum(ps_supplycost * ps_availqty) > ( select sum(ps_supplycost * ps_availqty) * 0.0000018542 from partsupp, supplier, nation where ps_suppkey = s_suppkey and s_nationkey = n_nationkey and (n_name = 'KENYA' or n_name = 'PERU') ) order by value desc;
select s_acctbal, s_name, n_name, p_partkey, p_mfgr, s_address, s_phone, s_comment from part, supplier, partsupp, nation, region where p_partkey = ps_partkey and s_suppkey = ps_suppkey and p_size = 17 and (p_type like '%COPPER') and s_nationkey = n_nationkey and n_regionkey = r_regionkey and (r_name = 'AFRICA' or r_name = 'EUROPE') and ps_supplycost = ( select min(ps_supplycost) from partsupp, supplier, nation, region where p_partkey = ps_partkey and s_suppkey = ps_suppkey and s_nationkey = n_nationkey and n_regionkey = r_regionkey and (r_name = 'AFRICA' or r_name = 'EUROPE') ) order by s_acctbal desc, n_name, s_name, p_partkey LIMIT 100;
select c_name, c_custkey, o_orderkey, o_orderdate, o_totalprice, sum(l_quantity) from customer, orders, lineitem where o_orderkey in ( select l_orderkey from lineitem group by l_orderkey having sum(l_quantity) > 204 ) and c_custkey = o_custkey and o_orderkey = l_orderkey group by c_name, c_custkey, o_orderkey, o_orderdate, o_totalprice order by o_totalprice desc, o_orderdate LIMIT 100;
select s_name, s_address from supplier, nation where s_suppkey in ( select ps_suppkey from partsupp where ps_partkey in ( select p_partkey from part where (p_name like '%lavender%' or p_name like '%brown%' or p_name like '%pink%' or p_name like '%green%') ) and ps_availqty > ( select 0.5 * sum(l_quantity) from lineitem where l_partkey = ps_partkey and l_suppkey = ps_suppkey and l_shipdate >= date '1992-12-24' and l_shipdate < DATE '1992-12-24' + INTERVAL 2 YEAR ) ) and s_nationkey = n_nationkey and n_name = 'CHINA' order by s_name;
select s_acctbal, s_name, n_name, p_partkey, p_mfgr, s_address, s_phone, s_comment from part, supplier, partsupp, nation, region where p_partkey = ps_partkey and s_suppkey = ps_suppkey and p_size = 16 and (p_type like '%TIN') and s_nationkey = n_nationkey and n_regionkey = r_regionkey and (r_name = 'AFRICA' or r_name = 'AMERICA' or r_name = 'MIDDLE EAST') and ps_supplycost = ( select min(ps_supplycost) from partsupp, supplier, nation, region where p_partkey = ps_partkey and s_suppkey = ps_suppkey and s_nationkey = n_nationkey and n_regionkey = r_regionkey and (r_name = 'AFRICA' or r_name = 'AMERICA' or r_name = 'MIDDLE EAST') ) order by s_acctbal desc, n_name, s_name, p_partkey LIMIT 100;
select l_returnflag, l_linestatus, sum(l_quantity) as sum_qty, sum(l_extendedprice) as sum_base_price, sum(l_extendedprice * (1 - l_discount)) as sum_disc_price, sum(l_extendedprice * (1 - l_discount) * (1 + l_tax)) as sum_charge, avg(l_quantity) as avg_qty, avg(l_extendedprice) as avg_price, avg(l_discount) as avg_disc, count(*) as count_order from lineitem where l_shipdate <= DATE '1994-06-04' - INTERVAL 99 DAY group by l_returnflag, l_linestatus order by l_returnflag, l_linestatus;
select l_returnflag, l_linestatus, sum(l_quantity) as sum_qty, sum(l_extendedprice) as sum_base_price, sum(l_extendedprice * (1 - l_discount)) as sum_disc_price, sum(l_extendedprice * (1 - l_discount) * (1 + l_tax)) as sum_charge, avg(l_quantity) as avg_qty, avg(l_extendedprice) as avg_price, avg(l_discount) as avg_disc, count(*) as count_order from lineitem where l_shipdate <= DATE '1998-04-30' - INTERVAL 99 DAY group by l_returnflag, l_linestatus order by l_returnflag, l_linestatus;
select sum(l_extendedprice * l_discount) as revenue from lineitem where l_shipdate >= date '1992-10-20' and l_shipdate < DATE '1992-10-20' + INTERVAL 4 YEAR and l_discount between 0.07 - 0.02 and 0.07 + 0.02 and l_quantity < 19;
select sum(l_extendedprice * (1 - l_discount)) as revenue from lineitem, part where ( p_partkey = l_partkey and p_brand = 'Brand#35' and p_container in ('SM PKG', 'MED CAN', 'LG JAR', 'SM BOX', 'LG PKG', 'WRAP BAG', 'MED CASE', 'LG DRUM') and l_quantity >= 12 and l_quantity <= 24 and p_size between 1 and 4 and l_shipmode in ('AIR', 'AIR REG') and l_shipinstruct = 'DELIVER IN PERSON' ) or ( p_partkey = l_partkey and p_brand = 'Brand#24' and p_container in ('WRAP CASE', 'JUMBO JAR', 'SM JAR', 'JUMBO PKG', 'SM PACK', 'LG JAR', 'JUMBO BAG', 'LG CASE') and l_quantity >= 16 and l_quantity <= 22 and p_size between 1 and 10 and l_shipmode in ('AIR', 'AIR REG') and l_shipinstruct = 'DELIVER IN PERSON' ) or ( p_partkey = l_partkey and p_brand = 'Brand#42' and p_container in ('LG CASE', 'WRAP JAR', 'SM BAG', 'JUMBO CASE', 'LG PKG', 'LG JAR', 'LG PACK', 'WRAP CAN') and l_quantity >= 34 and l_quantity <= 40 and p_size between 1 and 22 and l_shipmode in ('AIR', 'AIR REG') and l_shipinstruct = 'DELIVER IN PERSON' );
select sum(l_extendedprice) / 7.0 as avg_yearly from lineitem, part where p_partkey = l_partkey and p_brand = 'Brand#24' and (p_container = 'MED DRUM') and l_quantity < ( select 0.2 * avg(l_quantity) from lineitem where l_partkey = p_partkey );
select l_returnflag, l_linestatus, sum(l_quantity) as sum_qty, sum(l_extendedprice) as sum_base_price, sum(l_extendedprice * (1 - l_discount)) as sum_disc_price, sum(l_extendedprice * (1 - l_discount) * (1 + l_tax)) as sum_charge, avg(l_quantity) as avg_qty, avg(l_extendedprice) as avg_price, avg(l_discount) as avg_disc, count(*) as count_order from lineitem where l_shipdate <= DATE '1995-09-12' - INTERVAL 99 DAY group by l_returnflag, l_linestatus order by l_returnflag, l_linestatus;
select o_orderpriority, count(*) as order_count from orders where o_orderdate >= date '1995-12-01' and o_orderdate < DATE '1995-12-01' + INTERVAL 9 MONTH and exists ( select * from lineitem where l_orderkey = o_orderkey and l_commitdate < l_receiptdate ) group by o_orderpriority order by o_orderpriority;
select c_name, c_custkey, o_orderkey, o_orderdate, o_totalprice, sum(l_quantity) from customer, orders, lineitem where o_orderkey in ( select l_orderkey from lineitem group by l_orderkey having sum(l_quantity) > 55 ) and c_custkey = o_custkey and o_orderkey = l_orderkey group by c_name, c_custkey, o_orderkey, o_orderdate, o_totalprice order by o_totalprice desc, o_orderdate LIMIT 100;
select sum(l_extendedprice * l_discount) as revenue from lineitem where l_shipdate >= date '1994-09-30' and l_shipdate < DATE '1994-09-30' + INTERVAL 2 YEAR and l_discount between 0.05 - 0.03 and 0.05 + 0.03 and l_quantity < 15;
select nation, o_year, sum(amount) as sum_profit from ( select n_name as nation, extract(year from o_orderdate) as o_year, l_extendedprice * (1 - l_discount) - ps_supplycost * l_quantity as amount from part, supplier, lineitem, partsupp, orders, nation where s_suppkey = l_suppkey and ps_suppkey = l_suppkey and ps_partkey = l_partkey and p_partkey = l_partkey and o_orderkey = l_orderkey and s_nationkey = n_nationkey and p_name like '%lavender%' ) as profit group by nation, o_year order by nation, o_year desc;
select s_name, s_address from supplier, nation where s_suppkey in ( select ps_suppkey from partsupp where ps_partkey in ( select p_partkey from part where (p_name like '%lavender%' or p_name like '%orange%' or p_name like '%pink%' or p_name like '%brown%') ) and ps_availqty > ( select 0.5 * sum(l_quantity) from lineitem where l_partkey = ps_partkey and l_suppkey = ps_suppkey and l_shipdate >= date '1994-01-26' and l_shipdate < DATE '1994-01-26' + INTERVAL 1 YEAR ) ) and s_nationkey = n_nationkey and n_name = 'CHINA' order by s_name;
select l_shipmode, sum(case when o_orderpriority = '1-URGENT' or o_orderpriority = '2-HIGH' then 1 else 0 end) as high_line_count, sum(case when o_orderpriority <> '1-URGENT' and o_orderpriority <> '2-HIGH' then 1 else 0 end) as low_line_count from orders, lineitem where o_orderkey = l_orderkey and l_shipmode in ('FOB', 'REG AIR', 'TRUCK') and l_commitdate < l_receiptdate and l_shipdate < l_commitdate and l_receiptdate >= date '1992-08-14' and l_receiptdate < DATE '1992-08-14' + INTERVAL 3 YEAR group by l_shipmode order by l_shipmode;
select l_returnflag, l_linestatus, sum(l_quantity) as sum_qty, sum(l_extendedprice) as sum_base_price, sum(l_extendedprice * (1 - l_discount)) as sum_disc_price, sum(l_extendedprice * (1 - l_discount) * (1 + l_tax)) as sum_charge, avg(l_quantity) as avg_qty, avg(l_extendedprice) as avg_price, avg(l_discount) as avg_disc, count(*) as count_order from lineitem where l_shipdate <= DATE '1995-03-03' - INTERVAL 99 DAY group by l_returnflag, l_linestatus order by l_returnflag, l_linestatus;
select o_orderpriority, count(*) as order_count from orders where o_orderdate >= date '1995-12-01' and o_orderdate < DATE '1995-12-01' + INTERVAL 28 MONTH and exists ( select * from lineitem where l_orderkey = o_orderkey and l_commitdate < l_receiptdate ) group by o_orderpriority order by o_orderpriority;
select sum(l_extendedprice * (1 - l_discount)) as revenue from lineitem, part where ( p_partkey = l_partkey and p_brand = 'Brand#35' and p_container in ('JUMBO CAN', 'LG PACK', 'LG BOX', 'WRAP CAN', 'WRAP BAG', 'LG BAG', 'MED CASE') and l_quantity >= 6 and l_quantity <= 14 and p_size between 1 and 7 and l_shipmode in ('AIR', 'AIR REG') and l_shipinstruct = 'DELIVER IN PERSON' ) or ( p_partkey = l_partkey and p_brand = 'Brand#24' and p_container in ('MED PACK', 'MED CASE', 'SM CASE', 'WRAP BOX', 'MED PKG', 'JUMBO CASE', 'JUMBO JAR') and l_quantity >= 16 and l_quantity <= 27 and p_size between 1 and 11 and l_shipmode in ('AIR', 'AIR REG') and l_shipinstruct = 'DELIVER IN PERSON' ) or ( p_partkey = l_partkey and p_brand = 'Brand#42' and p_container in ('SM BOX', 'WRAP BOX', 'JUMBO BOX', 'JUMBO CAN', 'MED BOX', 'LG PKG', 'MED DRUM') and l_quantity >= 25 and l_quantity <= 33 and p_size between 1 and 24 and l_shipmode in ('AIR', 'AIR REG') and l_shipinstruct = 'DELIVER IN PERSON' );
select sum(l_extendedprice) / 7.0 as avg_yearly from lineitem, part where p_partkey = l_partkey and p_brand = 'Brand#24' and (p_container = 'MED JAR' or p_container = 'MED PKG' or p_container = 'LG PKG' or p_container = 'MED DRUM') and l_quantity < ( select 0.2 * avg(l_quantity) from lineitem where l_partkey = p_partkey );
select p_brand, p_type, p_size, count(distinct ps_suppkey) as supplier_cnt from partsupp, part where p_partkey = ps_partkey and p_brand <> 'Brand#52' and p_type not like 'STANDARD POLISHED%' and p_type not like 'ECONOMY ANODIZED%' and p_type not like 'SMALL BURNISHED%' and p_size in (27, 14, 11, 37, 50, 18, 20, 42) and ps_suppkey not in ( select s_suppkey from supplier where (s_comment like '%Customer%Returns%' or s_comment like '%Customer%Dislikes%') ) group by p_brand, p_type, p_size order by supplier_cnt desc, p_brand, p_type, p_size;
select c_name, c_custkey, o_orderkey, o_orderdate, o_totalprice, sum(l_quantity) from customer, orders, lineitem where o_orderkey in ( select l_orderkey from lineitem group by l_orderkey having sum(l_quantity) > 52 ) and c_custkey = o_custkey and o_orderkey = l_orderkey group by c_name, c_custkey, o_orderkey, o_orderdate, o_totalprice order by o_totalprice desc, o_orderdate LIMIT 100;
select ps_partkey, sum(ps_supplycost * ps_availqty) as value from partsupp, supplier, nation where ps_suppkey = s_suppkey and s_nationkey = n_nationkey and (n_name = 'INDONESIA') group by ps_partkey having sum(ps_supplycost * ps_availqty) > ( select sum(ps_supplycost * ps_availqty) * 0.0000009830 from partsupp, supplier, nation where ps_suppkey = s_suppkey and s_nationkey = n_nationkey and (n_name = 'INDONESIA') ) order by value desc;
select 100.00 * sum(case when p_type like 'PROMO%' then l_extendedprice * (1 - l_discount) else 0 end) / sum(l_extendedprice * (1 - l_discount)) as promo_revenue from lineitem, part where l_partkey = p_partkey and l_shipdate >= date '1994-08-12' and l_shipdate < DATE '1994-08-12' + INTERVAL 48 MONTH;
select s_name, s_address from supplier, nation where s_suppkey in ( select ps_suppkey from partsupp where ps_partkey in ( select p_partkey from part where (p_name like '%yellow%' or p_name like '%orange%' or p_name like '%lavender%' or p_name like '%pink%') ) and ps_availqty > ( select 0.5 * sum(l_quantity) from lineitem where l_partkey = ps_partkey and l_suppkey = ps_suppkey and l_shipdate >= date '1992-11-14' and l_shipdate < DATE '1992-11-14' + INTERVAL 1 YEAR ) ) and s_nationkey = n_nationkey and n_name = 'CHINA' order by s_name;
select sum(l_extendedprice) / 7.0 as avg_yearly from lineitem, part where p_partkey = l_partkey and p_brand = 'Brand#24' and (p_container = 'SM CAN' or p_container = 'JUMBO BOX' or p_container = 'MED DRUM') and l_quantity < ( select 0.2 * avg(l_quantity) from lineitem where l_partkey = p_partkey );
select sum(l_extendedprice * l_discount) as revenue from lineitem where l_shipdate >= date '1996-05-31' and l_shipdate < DATE '1996-05-31' + INTERVAL 3 YEAR and l_discount between 0.07 - 0.02 and 0.07 + 0.02 and l_quantity < 16;
select 100.00 * sum(case when p_type like 'PROMO%' then l_extendedprice * (1 - l_discount) else 0 end) / sum(l_extendedprice * (1 - l_discount)) as promo_revenue from lineitem, part where l_partkey = p_partkey and l_shipdate >= date '1992-07-29' and l_shipdate < DATE '1992-07-29' + INTERVAL 43 MONTH;
select sum(l_extendedprice * (1 - l_discount)) as revenue from lineitem, part where ( p_partkey = l_partkey and p_brand = 'Brand#35' and p_container in ('MED DRUM', 'SM PKG', 'SM CASE', 'JUMBO BAG') and l_quantity >= 5 and l_quantity <= 17 and p_size between 1 and 4 and l_shipmode in ('AIR', 'AIR REG') and l_shipinstruct = 'DELIVER IN PERSON' ) or ( p_partkey = l_partkey and p_brand = 'Brand#24' and p_container in ('LG CAN', 'WRAP BOX', 'MED BOX', 'LG BAG') and l_quantity >= 19 and l_quantity <= 28 and p_size between 1 and 7 and l_shipmode in ('AIR', 'AIR REG') and l_shipinstruct = 'DELIVER IN PERSON' ) or ( p_partkey = l_partkey and p_brand = 'Brand#42' and p_container in ('LG JAR', 'MED CAN', 'JUMBO PACK', 'LG CASE') and l_quantity >= 29 and l_quantity <= 41 and p_size between 1 and 24 and l_shipmode in ('AIR', 'AIR REG') and l_shipinstruct = 'DELIVER IN PERSON' );
select c_count, count(*) as custdist from ( select c_custkey, count(o_orderkey) as c_count from customer left outer join orders on c_custkey = o_custkey and o_comment not like '%pending%accounts%' and o_comment not like '%unusual%accounts%' group by c_custkey ) as c_orders group by c_count order by custdist desc, c_count desc;
select o_orderpriority, count(*) as order_count from orders where o_orderdate >= date '1995-12-01' and o_orderdate < DATE '1995-12-01' + INTERVAL 11 MONTH and exists ( select * from lineitem where l_orderkey = o_orderkey and l_commitdate < l_receiptdate ) group by o_orderpriority order by o_orderpriority;
select o_orderpriority, count(*) as order_count from orders where o_orderdate >= date '1995-12-01' and o_orderdate < DATE '1995-12-01' + INTERVAL 28 MONTH and exists ( select * from lineitem where l_orderkey = o_orderkey and l_commitdate < l_receiptdate ) group by o_orderpriority order by o_orderpriority;
select o_orderpriority, count(*) as order_count from orders where o_orderdate >= date '1995-12-01' and o_orderdate < DATE '1995-12-01' + INTERVAL 22 MONTH and exists ( select * from lineitem where l_orderkey = o_orderkey and l_commitdate < l_receiptdate ) group by o_orderpriority order by o_orderpriority;
select s_name, s_address from supplier, nation where s_suppkey in ( select ps_suppkey from partsupp where ps_partkey in ( select p_partkey from part where (p_name like '%brown%' or p_name like '%orange%') ) and ps_availqty > ( select 0.5 * sum(l_quantity) from lineitem where l_partkey = ps_partkey and l_suppkey = ps_suppkey and l_shipdate >= date '1994-11-04' and l_shipdate < DATE '1994-11-04' + INTERVAL 5 YEAR ) ) and s_nationkey = n_nationkey and n_name = 'CHINA' order by s_name;
select ps_partkey, sum(ps_supplycost * ps_availqty) as value from partsupp, supplier, nation where ps_suppkey = s_suppkey and s_nationkey = n_nationkey and (n_name = 'JORDAN' or n_name = 'ALGERIA') group by ps_partkey having sum(ps_supplycost * ps_availqty) > ( select sum(ps_supplycost * ps_availqty) * 0.0000013498 from partsupp, supplier, nation where ps_suppkey = s_suppkey and s_nationkey = n_nationkey and (n_name = 'JORDAN' or n_name = 'ALGERIA') ) order by value desc;
select l_returnflag, l_linestatus, sum(l_quantity) as sum_qty, sum(l_extendedprice) as sum_base_price, sum(l_extendedprice * (1 - l_discount)) as sum_disc_price, sum(l_extendedprice * (1 - l_discount) * (1 + l_tax)) as sum_charge, avg(l_quantity) as avg_qty, avg(l_extendedprice) as avg_price, avg(l_discount) as avg_disc, count(*) as count_order from lineitem where l_shipdate <= DATE '1994-05-30' - INTERVAL 99 DAY group by l_returnflag, l_linestatus order by l_returnflag, l_linestatus;
select 100.00 * sum(case when p_type like 'PROMO%' then l_extendedprice * (1 - l_discount) else 0 end) / sum(l_extendedprice * (1 - l_discount)) as promo_revenue from lineitem, part where l_partkey = p_partkey and l_shipdate >= date '1994-04-09' and l_shipdate < DATE '1994-04-09' + INTERVAL 50 MONTH;
select c_name, c_custkey, o_orderkey, o_orderdate, o_totalprice, sum(l_quantity) from customer, orders, lineitem where o_orderkey in ( select l_orderkey from lineitem group by l_orderkey having sum(l_quantity) > 68 ) and c_custkey = o_custkey and o_orderkey = l_orderkey group by c_name, c_custkey, o_orderkey, o_orderdate, o_totalprice order by o_totalprice desc, o_orderdate LIMIT 100;
select ps_partkey, sum(ps_supplycost * ps_availqty) as value from partsupp, supplier, nation where ps_suppkey = s_suppkey and s_nationkey = n_nationkey and (n_name = 'IRAN') group by ps_partkey having sum(ps_supplycost * ps_availqty) > ( select sum(ps_supplycost * ps_availqty) * 0.0000019396 from partsupp, supplier, nation where ps_suppkey = s_suppkey and s_nationkey = n_nationkey and (n_name = 'IRAN') ) order by value desc;
select s_acctbal, s_name, n_name, p_partkey, p_mfgr, s_address, s_phone, s_comment from part, supplier, partsupp, nation, region where p_partkey = ps_partkey and s_suppkey = ps_suppkey and p_size = 22 and (p_type like '%TIN') and s_nationkey = n_nationkey and n_regionkey = r_regionkey and (r_name = 'MIDDLE EAST' or r_name = 'AFRICA') and ps_supplycost = ( select min(ps_supplycost) from partsupp, supplier, nation, region where p_partkey = ps_partkey and s_suppkey = ps_suppkey and s_nationkey = n_nationkey and n_regionkey = r_regionkey and (r_name = 'MIDDLE EAST' or r_name = 'AFRICA') ) order by s_acctbal desc, n_name, s_name, p_partkey LIMIT 100;
