select ps_partkey, sum(ps_supplycost * ps_availqty) as value from partsupp, supplier, nation where ps_suppkey = s_suppkey and s_nationkey = n_nationkey and (n_name = 'SAUDI ARABIA') group by ps_partkey having sum(ps_supplycost * ps_availqty) > ( select sum(ps_supplycost * ps_availqty) * 0.0000004323 from partsupp, supplier, nation where ps_suppkey = s_suppkey and s_nationkey = n_nationkey and (n_name = 'SAUDI ARABIA') ) order by value desc;
select supp_nation, cust_nation, l_year, sum(volume) as revenue from ( select n1.n_name as supp_nation, n2.n_name as cust_nation, extract(year from l_shipdate) as l_year, l_extendedprice * (1 - l_discount) as volume from supplier, lineitem, orders, customer, nation n1, nation n2 where s_suppkey = l_suppkey and o_orderkey = l_orderkey and c_custkey = o_custkey and s_nationkey = n1.n_nationkey and c_nationkey = n2.n_nationkey and ((n1.n_name = 'UNITED KINGDOM' and n2.n_name = 'IRAN') or (n1.n_name = 'IRAN' and n2.n_name = 'UNITED KINGDOM')) and l_shipdate between date '1996-01-01' and date '1998-12-31' ) as shipping group by supp_nation, cust_nation, l_year order by supp_nation, cust_nation, l_year;
select sum(l_extendedprice * (1 - l_discount)) as revenue from lineitem, part where ( p_partkey = l_partkey and p_brand = 'Brand#35' and p_container in ('WRAP CAN', 'LG CAN', 'LG CASE', 'WRAP BAG', 'JUMBO BAG') and l_quantity >= 4 and l_quantity <= 11 and p_size between 1 and 7 and l_shipmode in ('AIR', 'AIR REG') and l_shipinstruct = 'DELIVER IN PERSON' ) or ( p_partkey = l_partkey and p_brand = 'Brand#24' and p_container in ('MED DRUM', 'SM BAG', 'LG BOX', 'JUMBO BAG', 'LG PACK') and l_quantity >= 18 and l_quantity <= 27 and p_size between 1 and 9 and l_shipmode in ('AIR', 'AIR REG') and l_shipinstruct = 'DELIVER IN PERSON' ) or ( p_partkey = l_partkey and p_brand = 'Brand#42' and p_container in ('MED PACK', 'WRAP DRUM', 'JUMBO DRUM', 'SM CAN', 'WRAP CAN') and l_quantity >= 25 and l_quantity <= 31 and p_size between 1 and 16 and l_shipmode in ('AIR', 'AIR REG') and l_shipinstruct = 'DELIVER IN PERSON' );
select 100.00 * sum(case when p_type like 'PROMO%' then l_extendedprice * (1 - l_discount) else 0 end) / sum(l_extendedprice * (1 - l_discount)) as promo_revenue from lineitem, part where l_partkey = p_partkey and l_shipdate >= date '1992-02-23' and l_shipdate < DATE '1992-02-23' + INTERVAL 15 MONTH;
select p_brand, p_type, p_size, count(distinct ps_suppkey) as supplier_cnt from partsupp, part where p_partkey = ps_partkey and p_brand <> 'Brand#52' and p_type not like 'STANDARD POLISHED%' and p_type not like 'ECONOMY ANODIZED%' and p_size in (14, 34, 33, 7, 10, 3, 17, 39) and ps_suppkey not in ( select s_suppkey from supplier where (s_comment like '%Customer%Issues%') ) group by p_brand, p_type, p_size order by supplier_cnt desc, p_brand, p_type, p_size;
select nation, o_year, sum(amount) as sum_profit from ( select n_name as nation, extract(year from o_orderdate) as o_year, l_extendedprice * (1 - l_discount) - ps_supplycost * l_quantity as amount from part, supplier, lineitem, partsupp, orders, nation where s_suppkey = l_suppkey and ps_suppkey = l_suppkey and ps_partkey = l_partkey and p_partkey = l_partkey and o_orderkey = l_orderkey and s_nationkey = n_nationkey and p_name like '%yellow%' ) as profit group by nation, o_year order by nation, o_year desc;
select sum(l_extendedprice * l_discount) as revenue from lineitem where l_shipdate >= date '1997-07-16' and l_shipdate < DATE '1997-07-16' + INTERVAL 5 YEAR and l_discount between 0.05 - 0.02 and 0.05 + 0.02 and l_quantity < 12;
select l_shipmode, sum(case when o_orderpriority = '1-URGENT' or o_orderpriority = '2-HIGH' then 1 else 0 end) as high_line_count, sum(case when o_orderpriority <> '1-URGENT' and o_orderpriority <> '2-HIGH' then 1 else 0 end) as low_line_count from orders, lineitem where o_orderkey = l_orderkey and l_shipmode in ('REG AIR', 'TRUCK', 'MAIL', 'AIR') and l_commitdate < l_receiptdate and l_shipdate < l_commitdate and l_receiptdate >= date '1995-09-25' and l_receiptdate < DATE '1995-09-25' + INTERVAL 4 YEAR group by l_shipmode order by l_shipmode;
select nation, o_year, sum(amount) as sum_profit from ( select n_name as nation, extract(year from o_orderdate) as o_year, l_extendedprice * (1 - l_discount) - ps_supplycost * l_quantity as amount from part, supplier, lineitem, partsupp, orders, nation where s_suppkey = l_suppkey and ps_suppkey = l_suppkey and ps_partkey = l_partkey and p_partkey = l_partkey and o_orderkey = l_orderkey and s_nationkey = n_nationkey and p_name like '%yellow%' ) as profit group by nation, o_year order by nation, o_year desc;
select s_name, s_address from supplier, nation where s_suppkey in ( select ps_suppkey from partsupp where ps_partkey in ( select p_partkey from part where (p_name like '%pink%' or p_name like '%brown%') ) and ps_availqty > ( select 0.5 * sum(l_quantity) from lineitem where l_partkey = ps_partkey and l_suppkey = ps_suppkey and l_shipdate >= date '1994-11-17' and l_shipdate < DATE '1994-11-17' + INTERVAL 5 YEAR ) ) and s_nationkey = n_nationkey and n_name = 'CHINA' order by s_name;
select s_name, s_address from supplier, nation where s_suppkey in ( select ps_suppkey from partsupp where ps_partkey in ( select p_partkey from part where (p_name like '%brown%') ) and ps_availqty > ( select 0.5 * sum(l_quantity) from lineitem where l_partkey = ps_partkey and l_suppkey = ps_suppkey and l_shipdate >= date '1993-07-25' and l_shipdate < DATE '1993-07-25' + INTERVAL 4 YEAR ) ) and s_nationkey = n_nationkey and n_name = 'CHINA' order by s_name;
select ps_partkey, sum(ps_supplycost * ps_availqty) as value from partsupp, supplier, nation where ps_suppkey = s_suppkey and s_nationkey = n_nationkey and (n_name = 'UNITED STATES') group by ps_partkey having sum(ps_supplycost * ps_availqty) > ( select sum(ps_supplycost * ps_availqty) * 0.0000006495 from partsupp, supplier, nation where ps_suppkey = s_suppkey and s_nationkey = n_nationkey and (n_name = 'UNITED STATES') ) order by value desc;
select s_name, s_address from supplier, nation where s_suppkey in ( select ps_suppkey from partsupp where ps_partkey in ( select p_partkey from part where (p_name like '%yellow%' or p_name like '%brown%' or p_name like '%orange%' or p_name like '%grey%') ) and ps_availqty > ( select 0.5 * sum(l_quantity) from lineitem where l_partkey = ps_partkey and l_suppkey = ps_suppkey and l_shipdate >= date '1992-06-29' and l_shipdate < DATE '1992-06-29' + INTERVAL 2 YEAR ) ) and s_nationkey = n_nationkey and n_name = 'CHINA' order by s_name;
select s_name, s_address from supplier, nation where s_suppkey in ( select ps_suppkey from partsupp where ps_partkey in ( select p_partkey from part where (p_name like '%blue%' or p_name like '%lavender%' or p_name like '%yellow%') ) and ps_availqty > ( select 0.5 * sum(l_quantity) from lineitem where l_partkey = ps_partkey and l_suppkey = ps_suppkey and l_shipdate >= date '1993-06-04' and l_shipdate < DATE '1993-06-04' + INTERVAL 1 YEAR ) ) and s_nationkey = n_nationkey and n_name = 'CHINA' order by s_name;
select s_acctbal, s_name, n_name, p_partkey, p_mfgr, s_address, s_phone, s_comment from part, supplier, partsupp, nation, region where p_partkey = ps_partkey and s_suppkey = ps_suppkey and p_size = 37 and (p_type like '%STEEL') and s_nationkey = n_nationkey and n_regionkey = r_regionkey and (r_name = 'ASIA' or r_name = 'AFRICA' or r_name = 'AMERICA') and ps_supplycost = ( select min(ps_supplycost) from partsupp, supplier, nation, region where p_partkey = ps_partkey and s_suppkey = ps_suppkey and s_nationkey = n_nationkey and n_regionkey = r_regionkey and (r_name = 'ASIA' or r_name = 'AFRICA' or r_name = 'AMERICA') ) order by s_acctbal desc, n_name, s_name, p_partkey LIMIT 100;
select sum(l_extendedprice * l_discount) as revenue from lineitem where l_shipdate >= date '1994-05-29' and l_shipdate < DATE '1994-05-29' + INTERVAL 1 YEAR and l_discount between 0.07 - 0.02 and 0.07 + 0.02 and l_quantity < 25;
select l_shipmode, sum(case when o_orderpriority = '1-URGENT' or o_orderpriority = '2-HIGH' then 1 else 0 end) as high_line_count, sum(case when o_orderpriority <> '1-URGENT' and o_orderpriority <> '2-HIGH' then 1 else 0 end) as low_line_count from orders, lineitem where o_orderkey = l_orderkey and l_shipmode in ('SHIP', 'AIR', 'RAIL') and l_commitdate < l_receiptdate and l_shipdate < l_commitdate and l_receiptdate >= date '1995-04-24' and l_receiptdate < DATE '1995-04-24' + INTERVAL 6 YEAR group by l_shipmode order by l_shipmode;
select c_count, count(*) as custdist from ( select c_custkey, count(o_orderkey) as c_count from customer left outer join orders on c_custkey = o_custkey and o_comment not like '%pending%accounts%' and o_comment not like '%pending%requests%' group by c_custkey ) as c_orders group by c_count order by custdist desc, c_count desc;
select nation, o_year, sum(amount) as sum_profit from ( select n_name as nation, extract(year from o_orderdate) as o_year, l_extendedprice * (1 - l_discount) - ps_supplycost * l_quantity as amount from part, supplier, lineitem, partsupp, orders, nation where s_suppkey = l_suppkey and ps_suppkey = l_suppkey and ps_partkey = l_partkey and p_partkey = l_partkey and o_orderkey = l_orderkey and s_nationkey = n_nationkey and p_name like '%purple%' ) as profit group by nation, o_year order by nation, o_year desc;
select p_brand, p_type, p_size, count(distinct ps_suppkey) as supplier_cnt from partsupp, part where p_partkey = ps_partkey and p_brand <> 'Brand#52' and p_type not like 'MEDIUM POLISHED%' and p_type not like 'LARGE POLISHED%' and p_size in (33, 8, 6, 40, 37, 35, 18, 34) and ps_suppkey not in ( select s_suppkey from supplier where (s_comment like '%Customer%Problems%' or s_comment like '%Customer%Returns%' or s_comment like '%Customer%Complaints%') ) group by p_brand, p_type, p_size order by supplier_cnt desc, p_brand, p_type, p_size;
