select sum(l_extendedprice * (1 - l_discount)) as revenue from lineitem, part where ( p_partkey = l_partkey and p_brand = 'Brand#35' and p_container in ('SM DRUM', 'WRAP BAG', 'JUMBO CASE', 'LG DRUM', 'WRAP JAR', 'JUMBO PACK') and l_quantity >= 4 and l_quantity <= 14 and p_size between 1 and 5 and l_shipmode in ('AIR', 'AIR REG') and l_shipinstruct = 'DELIVER IN PERSON' ) or ( p_partkey = l_partkey and p_brand = 'Brand#24' and p_container in ('WRAP BOX', 'MED PACK', 'LG PACK', 'LG CAN', 'SM CASE', 'MED JAR') and l_quantity >= 15 and l_quantity <= 26 and p_size between 1 and 12 and l_shipmode in ('AIR', 'AIR REG') and l_shipinstruct = 'DELIVER IN PERSON' ) or ( p_partkey = l_partkey and p_brand = 'Brand#42' and p_container in ('JUMBO DRUM', 'JUMBO JAR', 'MED JAR', 'MED DRUM', 'JUMBO PKG', 'WRAP JAR') and l_quantity >= 29 and l_quantity <= 35 and p_size between 1 and 23 and l_shipmode in ('AIR', 'AIR REG') and l_shipinstruct = 'DELIVER IN PERSON' );
select c_count, count(*) as custdist from ( select c_custkey, count(o_orderkey) as c_count from customer left outer join orders on c_custkey = o_custkey and o_comment not like '%express%packages%' group by c_custkey ) as c_orders group by c_count order by custdist desc, c_count desc;
select sum(l_extendedprice) / 7.0 as avg_yearly from lineitem, part where p_partkey = l_partkey and p_brand = 'Brand#24' and (p_container = 'WRAP BOX' or p_container = 'LG PACK' or p_container = 'LG BAG' or p_container = 'JUMBO CAN') and l_quantity < ( select 0.2 * avg(l_quantity) from lineitem where l_partkey = p_partkey );
select o_orderpriority, count(*) as order_count from orders where o_orderdate >= date '1995-12-01' and o_orderdate < DATE '1995-12-01' + INTERVAL 16 MONTH and exists ( select * from lineitem where l_orderkey = o_orderkey and l_commitdate < l_receiptdate ) group by o_orderpriority order by o_orderpriority;
select s_acctbal, s_name, n_name, p_partkey, p_mfgr, s_address, s_phone, s_comment from part, supplier, partsupp, nation, region where p_partkey = ps_partkey and s_suppkey = ps_suppkey and p_size = 13 and (p_type like '%COPPER' or p_type like '%BRASS' or p_type like '%NICKEL') and s_nationkey = n_nationkey and n_regionkey = r_regionkey and (r_name = 'AMERICA') and ps_supplycost = ( select min(ps_supplycost) from partsupp, supplier, nation, region where p_partkey = ps_partkey and s_suppkey = ps_suppkey and s_nationkey = n_nationkey and n_regionkey = r_regionkey and (r_name = 'AMERICA') ) order by s_acctbal desc, n_name, s_name, p_partkey LIMIT 100;
select p_brand, p_type, p_size, count(distinct ps_suppkey) as supplier_cnt from partsupp, part where p_partkey = ps_partkey and p_brand <> 'Brand#52' and p_type not like 'ECONOMY ANODIZED%' and p_size in (13, 9, 30, 24, 50, 25, 8, 41) and ps_suppkey not in ( select s_suppkey from supplier where (s_comment like '%Customer%Dislikes%' or s_comment like '%Customer%Damages%') ) group by p_brand, p_type, p_size order by supplier_cnt desc, p_brand, p_type, p_size;
select c_count, count(*) as custdist from ( select c_custkey, count(o_orderkey) as c_count from customer left outer join orders on c_custkey = o_custkey and o_comment not like '%unusual%requests%' group by c_custkey ) as c_orders group by c_count order by custdist desc, c_count desc;
select sum(l_extendedprice * l_discount) as revenue from lineitem where l_shipdate >= date '1996-04-06' and l_shipdate < DATE '1996-04-06' + INTERVAL 1 YEAR and l_discount between 0.06 - 0.02 and 0.06 + 0.02 and l_quantity < 11;
select sum(l_extendedprice * l_discount) as revenue from lineitem where l_shipdate >= date '1995-05-08' and l_shipdate < DATE '1995-05-08' + INTERVAL 3 YEAR and l_discount between 0.09 - 0.02 and 0.09 + 0.02 and l_quantity < 11;
select c_count, count(*) as custdist from ( select c_custkey, count(o_orderkey) as c_count from customer left outer join orders on c_custkey = o_custkey and o_comment not like '%unusual%packages%' and o_comment not like '%special%requests%' and o_comment not like '%special%packages%' group by c_custkey ) as c_orders group by c_count order by custdist desc, c_count desc;
