select sum(l_extendedprice) / 7.0 as avg_yearly from lineitem, part where p_partkey = l_partkey and p_brand = 'Brand#24' and (p_container = 'SM BAG' or p_container = 'WRAP DRUM') and l_quantity < ( select 0.2 * avg(l_quantity) from lineitem where l_partkey = p_partkey );
select o_orderpriority, count(*) as order_count from orders where o_orderdate >= date '1995-12-01' and o_orderdate < DATE '1995-12-01' + INTERVAL 5 MONTH and exists ( select * from lineitem where l_orderkey = o_orderkey and l_commitdate < l_receiptdate ) group by o_orderpriority order by o_orderpriority;
select s_name, s_address from supplier, nation where s_suppkey in ( select ps_suppkey from partsupp where ps_partkey in ( select p_partkey from part where (p_name like '%green%' or p_name like '%brown%' or p_name like '%purple%' or p_name like '%yellow%') ) and ps_availqty > ( select 0.5 * sum(l_quantity) from lineitem where l_partkey = ps_partkey and l_suppkey = ps_suppkey and l_shipdate >= date '1993-08-24' and l_shipdate < DATE '1993-08-24' + INTERVAL 5 YEAR ) ) and s_nationkey = n_nationkey and n_name = 'CHINA' order by s_name;
select sum(l_extendedprice * l_discount) as revenue from lineitem where l_shipdate >= date '1997-03-07' and l_shipdate < DATE '1997-03-07' + INTERVAL 1 YEAR and l_discount between 0.08 - 0.03 and 0.08 + 0.03 and l_quantity < 29;
select ps_partkey, sum(ps_supplycost * ps_availqty) as value from partsupp, supplier, nation where ps_suppkey = s_suppkey and s_nationkey = n_nationkey and (n_name = 'MOZAMBIQUE' or n_name = 'RUSSIA' or n_name = 'BRAZIL') group by ps_partkey having sum(ps_supplycost * ps_availqty) > ( select sum(ps_supplycost * ps_availqty) * 0.0000018253 from partsupp, supplier, nation where ps_suppkey = s_suppkey and s_nationkey = n_nationkey and (n_name = 'MOZAMBIQUE' or n_name = 'RUSSIA' or n_name = 'BRAZIL') ) order by value desc;
select c_count, count(*) as custdist from ( select c_custkey, count(o_orderkey) as c_count from customer left outer join orders on c_custkey = o_custkey and o_comment not like '%unusual%requests%' and o_comment not like '%express%accounts%' and o_comment not like '%special%requests%' group by c_custkey ) as c_orders group by c_count order by custdist desc, c_count desc;
select sum(l_extendedprice) / 7.0 as avg_yearly from lineitem, part where p_partkey = l_partkey and p_brand = 'Brand#24' and (p_container = 'LG PKG') and l_quantity < ( select 0.2 * avg(l_quantity) from lineitem where l_partkey = p_partkey );
select p_brand, p_type, p_size, count(distinct ps_suppkey) as supplier_cnt from partsupp, part where p_partkey = ps_partkey and p_brand <> 'Brand#52' and p_type not like 'SMALL BURNISHED%' and p_type not like 'LARGE POLISHED%' and p_size in (23, 41, 18, 9, 7, 24, 6, 40) and ps_suppkey not in ( select s_suppkey from supplier where (s_comment like '%Customer%Returns%' or s_comment like '%Customer%Dislikes%' or s_comment like '%Customer%Problems%') ) group by p_brand, p_type, p_size order by supplier_cnt desc, p_brand, p_type, p_size;
select sum(l_extendedprice) / 7.0 as avg_yearly from lineitem, part where p_partkey = l_partkey and p_brand = 'Brand#24' and (p_container = 'LG BOX' or p_container = 'SM CASE') and l_quantity < ( select 0.2 * avg(l_quantity) from lineitem where l_partkey = p_partkey );
select p_brand, p_type, p_size, count(distinct ps_suppkey) as supplier_cnt from partsupp, part where p_partkey = ps_partkey and p_brand <> 'Brand#52' and p_type not like 'ECONOMY ANODIZED%' and p_type not like 'STANDARD POLISHED%' and p_type not like 'MEDIUM POLISHED%' and p_size in (30, 23, 19, 15, 8, 11, 35, 1) and ps_suppkey not in ( select s_suppkey from supplier where (s_comment like '%Customer%Dislikes%' or s_comment like '%Customer%Returns%') ) group by p_brand, p_type, p_size order by supplier_cnt desc, p_brand, p_type, p_size;
select c_name, c_custkey, o_orderkey, o_orderdate, o_totalprice, sum(l_quantity) from customer, orders, lineitem where o_orderkey in ( select l_orderkey from lineitem group by l_orderkey having sum(l_quantity) > 217 ) and c_custkey = o_custkey and o_orderkey = l_orderkey group by c_name, c_custkey, o_orderkey, o_orderdate, o_totalprice order by o_totalprice desc, o_orderdate LIMIT 100;
select s_acctbal, s_name, n_name, p_partkey, p_mfgr, s_address, s_phone, s_comment from part, supplier, partsupp, nation, region where p_partkey = ps_partkey and s_suppkey = ps_suppkey and p_size = 18 and (p_type like '%BRASS') and s_nationkey = n_nationkey and n_regionkey = r_regionkey and (r_name = 'MIDDLE EAST') and ps_supplycost = ( select min(ps_supplycost) from partsupp, supplier, nation, region where p_partkey = ps_partkey and s_suppkey = ps_suppkey and s_nationkey = n_nationkey and n_regionkey = r_regionkey and (r_name = 'MIDDLE EAST') ) order by s_acctbal desc, n_name, s_name, p_partkey LIMIT 100;
select sum(l_extendedprice * (1 - l_discount)) as revenue from lineitem, part where ( p_partkey = l_partkey and p_brand = 'Brand#35' and p_container in ('MED CAN', 'WRAP BAG', 'LG CAN', 'WRAP PKG', 'MED JAR', 'LG CASE') and l_quantity >= 10 and l_quantity <= 17 and p_size between 1 and 3 and l_shipmode in ('AIR', 'AIR REG') and l_shipinstruct = 'DELIVER IN PERSON' ) or ( p_partkey = l_partkey and p_brand = 'Brand#24' and p_container in ('SM PACK', 'MED CAN', 'SM PKG', 'JUMBO BOX', 'WRAP CAN', 'JUMBO CASE') and l_quantity >= 17 and l_quantity <= 26 and p_size between 1 and 8 and l_shipmode in ('AIR', 'AIR REG') and l_shipinstruct = 'DELIVER IN PERSON' ) or ( p_partkey = l_partkey and p_brand = 'Brand#42' and p_container in ('SM CASE', 'JUMBO CASE', 'MED DRUM', 'SM PKG', 'JUMBO BAG', 'MED PACK') and l_quantity >= 28 and l_quantity <= 35 and p_size between 1 and 11 and l_shipmode in ('AIR', 'AIR REG') and l_shipinstruct = 'DELIVER IN PERSON' );
select c_count, count(*) as custdist from ( select c_custkey, count(o_orderkey) as c_count from customer left outer join orders on c_custkey = o_custkey and o_comment not like '%pending%accounts%' group by c_custkey ) as c_orders group by c_count order by custdist desc, c_count desc;
select l_returnflag, l_linestatus, sum(l_quantity) as sum_qty, sum(l_extendedprice) as sum_base_price, sum(l_extendedprice * (1 - l_discount)) as sum_disc_price, sum(l_extendedprice * (1 - l_discount) * (1 + l_tax)) as sum_charge, avg(l_quantity) as avg_qty, avg(l_extendedprice) as avg_price, avg(l_discount) as avg_disc, count(*) as count_order from lineitem where l_shipdate <= DATE '1994-08-03' - INTERVAL 99 DAY group by l_returnflag, l_linestatus order by l_returnflag, l_linestatus;
select sum(l_extendedprice * l_discount) as revenue from lineitem where l_shipdate >= date '1992-07-12' and l_shipdate < DATE '1992-07-12' + INTERVAL 4 YEAR and l_discount between 0.04 - 0.02 and 0.04 + 0.02 and l_quantity < 22;
select 100.00 * sum(case when p_type like 'PROMO%' then l_extendedprice * (1 - l_discount) else 0 end) / sum(l_extendedprice * (1 - l_discount)) as promo_revenue from lineitem, part where l_partkey = p_partkey and l_shipdate >= date '1993-09-10' and l_shipdate < DATE '1993-09-10' + INTERVAL 5 MONTH;
select l_shipmode, sum(case when o_orderpriority = '1-URGENT' or o_orderpriority = '2-HIGH' then 1 else 0 end) as high_line_count, sum(case when o_orderpriority <> '1-URGENT' and o_orderpriority <> '2-HIGH' then 1 else 0 end) as low_line_count from orders, lineitem where o_orderkey = l_orderkey and l_shipmode in ('FOB', 'MAIL', 'SHIP', 'TRUCK') and l_commitdate < l_receiptdate and l_shipdate < l_commitdate and l_receiptdate >= date '1998-04-30' and l_receiptdate < DATE '1998-04-30' + INTERVAL 5 YEAR group by l_shipmode order by l_shipmode;
select l_returnflag, l_linestatus, sum(l_quantity) as sum_qty, sum(l_extendedprice) as sum_base_price, sum(l_extendedprice * (1 - l_discount)) as sum_disc_price, sum(l_extendedprice * (1 - l_discount) * (1 + l_tax)) as sum_charge, avg(l_quantity) as avg_qty, avg(l_extendedprice) as avg_price, avg(l_discount) as avg_disc, count(*) as count_order from lineitem where l_shipdate <= DATE '1994-02-21' - INTERVAL 99 DAY group by l_returnflag, l_linestatus order by l_returnflag, l_linestatus;
