select l_shipmode, sum(case when o_orderpriority = '1-URGENT' or o_orderpriority = '2-HIGH' then 1 else 0 end) as high_line_count, sum(case when o_orderpriority <> '1-URGENT' and o_orderpriority <> '2-HIGH' then 1 else 0 end) as low_line_count from orders, lineitem where o_orderkey = l_orderkey and l_shipmode in ('REG AIR', 'TRUCK') and l_commitdate < l_receiptdate and l_shipdate < l_commitdate and l_receiptdate >= date '1993-12-22' and l_receiptdate < DATE '1993-12-22' + INTERVAL 1 YEAR group by l_shipmode order by l_shipmode;
select o_orderpriority, count(*) as order_count from orders where o_orderdate >= date '1995-12-01' and o_orderdate < DATE '1995-12-01' + INTERVAL 34 MONTH and exists ( select * from lineitem where l_orderkey = o_orderkey and l_commitdate < l_receiptdate ) group by o_orderpriority order by o_orderpriority;
select c_count, count(*) as custdist from ( select c_custkey, count(o_orderkey) as c_count from customer left outer join orders on c_custkey = o_custkey and o_comment not like '%special%packages%' and o_comment not like '%pending%requests%' group by c_custkey ) as c_orders group by c_count order by custdist desc, c_count desc;
select l_returnflag, l_linestatus, sum(l_quantity) as sum_qty, sum(l_extendedprice) as sum_base_price, sum(l_extendedprice * (1 - l_discount)) as sum_disc_price, sum(l_extendedprice * (1 - l_discount) * (1 + l_tax)) as sum_charge, avg(l_quantity) as avg_qty, avg(l_extendedprice) as avg_price, avg(l_discount) as avg_disc, count(*) as count_order from lineitem where l_shipdate <= DATE '1996-02-12' - INTERVAL 99 DAY group by l_returnflag, l_linestatus order by l_returnflag, l_linestatus;
select sum(l_extendedprice * l_discount) as revenue from lineitem where l_shipdate >= date '1995-12-28' and l_shipdate < DATE '1995-12-28' + INTERVAL 5 YEAR and l_discount between 0.05 - 0.03 and 0.05 + 0.03 and l_quantity < 23;
select s_acctbal, s_name, n_name, p_partkey, p_mfgr, s_address, s_phone, s_comment from part, supplier, partsupp, nation, region where p_partkey = ps_partkey and s_suppkey = ps_suppkey and p_size = 39 and (p_type like '%TIN') and s_nationkey = n_nationkey and n_regionkey = r_regionkey and (r_name = 'AFRICA' or r_name = 'MIDDLE EAST' or r_name = 'EUROPE') and ps_supplycost = ( select min(ps_supplycost) from partsupp, supplier, nation, region where p_partkey = ps_partkey and s_suppkey = ps_suppkey and s_nationkey = n_nationkey and n_regionkey = r_regionkey and (r_name = 'AFRICA' or r_name = 'MIDDLE EAST' or r_name = 'EUROPE') ) order by s_acctbal desc, n_name, s_name, p_partkey LIMIT 100;
select p_brand, p_type, p_size, count(distinct ps_suppkey) as supplier_cnt from partsupp, part where p_partkey = ps_partkey and p_brand <> 'Brand#52' and p_type not like 'SMALL BURNISHED%' and p_size in (50, 29, 8, 15, 28, 19, 32, 43) and ps_suppkey not in ( select s_suppkey from supplier where (s_comment like '%Customer%Problems%') ) group by p_brand, p_type, p_size order by supplier_cnt desc, p_brand, p_type, p_size;
select ps_partkey, sum(ps_supplycost * ps_availqty) as value from partsupp, supplier, nation where ps_suppkey = s_suppkey and s_nationkey = n_nationkey and (n_name = 'ARGENTINA' or n_name = 'INDIA' or n_name = 'RUSSIA') group by ps_partkey having sum(ps_supplycost * ps_availqty) > ( select sum(ps_supplycost * ps_availqty) * 0.0000017299 from partsupp, supplier, nation where ps_suppkey = s_suppkey and s_nationkey = n_nationkey and (n_name = 'ARGENTINA' or n_name = 'INDIA' or n_name = 'RUSSIA') ) order by value desc;
select c_name, c_custkey, o_orderkey, o_orderdate, o_totalprice, sum(l_quantity) from customer, orders, lineitem where o_orderkey in ( select l_orderkey from lineitem group by l_orderkey having sum(l_quantity) > 92 ) and c_custkey = o_custkey and o_orderkey = l_orderkey group by c_name, c_custkey, o_orderkey, o_orderdate, o_totalprice order by o_totalprice desc, o_orderdate LIMIT 100;
select 100.00 * sum(case when p_type like 'PROMO%' then l_extendedprice * (1 - l_discount) else 0 end) / sum(l_extendedprice * (1 - l_discount)) as promo_revenue from lineitem, part where l_partkey = p_partkey and l_shipdate >= date '1994-04-01' and l_shipdate < DATE '1994-04-01' + INTERVAL 4 MONTH;
select sum(l_extendedprice) / 7.0 as avg_yearly from lineitem, part where p_partkey = l_partkey and p_brand = 'Brand#24' and (p_container = 'LG PACK' or p_container = 'SM CAN' or p_container = 'WRAP PACK') and l_quantity < ( select 0.2 * avg(l_quantity) from lineitem where l_partkey = p_partkey );
select s_name, s_address from supplier, nation where s_suppkey in ( select ps_suppkey from partsupp where ps_partkey in ( select p_partkey from part where (p_name like '%lavender%' or p_name like '%purple%') ) and ps_availqty > ( select 0.5 * sum(l_quantity) from lineitem where l_partkey = ps_partkey and l_suppkey = ps_suppkey and l_shipdate >= date '1992-09-20' and l_shipdate < DATE '1992-09-20' + INTERVAL 3 YEAR ) ) and s_nationkey = n_nationkey and n_name = 'CHINA' order by s_name;
select sum(l_extendedprice * (1 - l_discount)) as revenue from lineitem, part where ( p_partkey = l_partkey and p_brand = 'Brand#35' and p_container in ('JUMBO BAG', 'WRAP PKG', 'WRAP CAN', 'SM DRUM', 'LG PACK', 'WRAP BAG') and l_quantity >= 7 and l_quantity <= 15 and p_size between 1 and 3 and l_shipmode in ('AIR', 'AIR REG') and l_shipinstruct = 'DELIVER IN PERSON' ) or ( p_partkey = l_partkey and p_brand = 'Brand#24' and p_container in ('JUMBO PACK', 'MED CASE', 'LG PKG', 'LG CASE', 'SM PKG', 'WRAP CAN') and l_quantity >= 17 and l_quantity <= 23 and p_size between 1 and 15 and l_shipmode in ('AIR', 'AIR REG') and l_shipinstruct = 'DELIVER IN PERSON' ) or ( p_partkey = l_partkey and p_brand = 'Brand#42' and p_container in ('SM DRUM', 'LG CASE', 'SM PACK', 'JUMBO PKG', 'MED PKG', 'JUMBO CAN') and l_quantity >= 24 and l_quantity <= 32 and p_size between 1 and 14 and l_shipmode in ('AIR', 'AIR REG') and l_shipinstruct = 'DELIVER IN PERSON' );
select sum(l_extendedprice * (1 - l_discount)) as revenue from lineitem, part where ( p_partkey = l_partkey and p_brand = 'Brand#35' and p_container in ('MED BAG', 'SM PACK', 'LG BOX', 'JUMBO CASE', 'MED PKG', 'MED CAN') and l_quantity >= 8 and l_quantity <= 20 and p_size between 1 and 7 and l_shipmode in ('AIR', 'AIR REG') and l_shipinstruct = 'DELIVER IN PERSON' ) or ( p_partkey = l_partkey and p_brand = 'Brand#24' and p_container in ('JUMBO JAR', 'WRAP PKG', 'MED BOX', 'JUMBO BOX', 'JUMBO BAG', 'LG PACK') and l_quantity >= 20 and l_quantity <= 31 and p_size between 1 and 9 and l_shipmode in ('AIR', 'AIR REG') and l_shipinstruct = 'DELIVER IN PERSON' ) or ( p_partkey = l_partkey and p_brand = 'Brand#42' and p_container in ('LG CASE', 'SM DRUM', 'LG BOX', 'MED PACK', 'WRAP CASE', 'JUMBO DRUM') and l_quantity >= 34 and l_quantity <= 46 and p_size between 1 and 21 and l_shipmode in ('AIR', 'AIR REG') and l_shipinstruct = 'DELIVER IN PERSON' );
select c_count, count(*) as custdist from ( select c_custkey, count(o_orderkey) as c_count from customer left outer join orders on c_custkey = o_custkey and o_comment not like '%express%packages%' and o_comment not like '%special%accounts%' and o_comment not like '%unusual%requests%' group by c_custkey ) as c_orders group by c_count order by custdist desc, c_count desc;
select supp_nation, cust_nation, l_year, sum(volume) as revenue from ( select n1.n_name as supp_nation, n2.n_name as cust_nation, extract(year from l_shipdate) as l_year, l_extendedprice * (1 - l_discount) as volume from supplier, lineitem, orders, customer, nation n1, nation n2 where s_suppkey = l_suppkey and o_orderkey = l_orderkey and c_custkey = o_custkey and s_nationkey = n1.n_nationkey and c_nationkey = n2.n_nationkey and ((n1.n_name = 'PERU' and n2.n_name = 'IRAN') or (n1.n_name = 'IRAN' and n2.n_name = 'PERU')) and l_shipdate between date '1994-01-01' and date '1995-12-31' ) as shipping group by supp_nation, cust_nation, l_year order by supp_nation, cust_nation, l_year;
select sum(l_extendedprice) / 7.0 as avg_yearly from lineitem, part where p_partkey = l_partkey and p_brand = 'Brand#24' and (p_container = 'WRAP BOX') and l_quantity < ( select 0.2 * avg(l_quantity) from lineitem where l_partkey = p_partkey );
select s_acctbal, s_name, n_name, p_partkey, p_mfgr, s_address, s_phone, s_comment from part, supplier, partsupp, nation, region where p_partkey = ps_partkey and s_suppkey = ps_suppkey and p_size = 46 and (p_type like '%TIN') and s_nationkey = n_nationkey and n_regionkey = r_regionkey and (r_name = 'EUROPE' or r_name = 'AFRICA') and ps_supplycost = ( select min(ps_supplycost) from partsupp, supplier, nation, region where p_partkey = ps_partkey and s_suppkey = ps_suppkey and s_nationkey = n_nationkey and n_regionkey = r_regionkey and (r_name = 'EUROPE' or r_name = 'AFRICA') ) order by s_acctbal desc, n_name, s_name, p_partkey LIMIT 100;
select 100.00 * sum(case when p_type like 'PROMO%' then l_extendedprice * (1 - l_discount) else 0 end) / sum(l_extendedprice * (1 - l_discount)) as promo_revenue from lineitem, part where l_partkey = p_partkey and l_shipdate >= date '1994-10-22' and l_shipdate < DATE '1994-10-22' + INTERVAL 26 MONTH;
select l_returnflag, l_linestatus, sum(l_quantity) as sum_qty, sum(l_extendedprice) as sum_base_price, sum(l_extendedprice * (1 - l_discount)) as sum_disc_price, sum(l_extendedprice * (1 - l_discount) * (1 + l_tax)) as sum_charge, avg(l_quantity) as avg_qty, avg(l_extendedprice) as avg_price, avg(l_discount) as avg_disc, count(*) as count_order from lineitem where l_shipdate <= DATE '1994-09-30' - INTERVAL 99 DAY group by l_returnflag, l_linestatus order by l_returnflag, l_linestatus;
select p_brand, p_type, p_size, count(distinct ps_suppkey) as supplier_cnt from partsupp, part where p_partkey = ps_partkey and p_brand <> 'Brand#52' and p_type not like 'LARGE POLISHED%' and p_type not like 'ECONOMY ANODIZED%' and p_size in (46, 12, 29, 48, 31, 27, 2, 26) and ps_suppkey not in ( select s_suppkey from supplier where (s_comment like '%Customer%Damages%' or s_comment like '%Customer%Complaints%') ) group by p_brand, p_type, p_size order by supplier_cnt desc, p_brand, p_type, p_size;
select c_name, c_custkey, o_orderkey, o_orderdate, o_totalprice, sum(l_quantity) from customer, orders, lineitem where o_orderkey in ( select l_orderkey from lineitem group by l_orderkey having sum(l_quantity) > 50 ) and c_custkey = o_custkey and o_orderkey = l_orderkey group by c_name, c_custkey, o_orderkey, o_orderdate, o_totalprice order by o_totalprice desc, o_orderdate LIMIT 100;
select sum(l_extendedprice * l_discount) as revenue from lineitem where l_shipdate >= date '1997-05-21' and l_shipdate < DATE '1997-05-21' + INTERVAL 5 YEAR and l_discount between 0.06 - 0.01 and 0.06 + 0.01 and l_quantity < 17;
select nation, o_year, sum(amount) as sum_profit from ( select n_name as nation, extract(year from o_orderdate) as o_year, l_extendedprice * (1 - l_discount) - ps_supplycost * l_quantity as amount from part, supplier, lineitem, partsupp, orders, nation where s_suppkey = l_suppkey and ps_suppkey = l_suppkey and ps_partkey = l_partkey and p_partkey = l_partkey and o_orderkey = l_orderkey and s_nationkey = n_nationkey and p_name like '%lavender%' ) as profit group by nation, o_year order by nation, o_year desc;
select sum(l_extendedprice) / 7.0 as avg_yearly from lineitem, part where p_partkey = l_partkey and p_brand = 'Brand#24' and (p_container = 'MED CAN' or p_container = 'LG JAR' or p_container = 'JUMBO CASE' or p_container = 'JUMBO DRUM') and l_quantity < ( select 0.2 * avg(l_quantity) from lineitem where l_partkey = p_partkey );
select nation, o_year, sum(amount) as sum_profit from ( select n_name as nation, extract(year from o_orderdate) as o_year, l_extendedprice * (1 - l_discount) - ps_supplycost * l_quantity as amount from part, supplier, lineitem, partsupp, orders, nation where s_suppkey = l_suppkey and ps_suppkey = l_suppkey and ps_partkey = l_partkey and p_partkey = l_partkey and o_orderkey = l_orderkey and s_nationkey = n_nationkey and p_name like '%grey%' ) as profit group by nation, o_year order by nation, o_year desc;
select p_brand, p_type, p_size, count(distinct ps_suppkey) as supplier_cnt from partsupp, part where p_partkey = ps_partkey and p_brand <> 'Brand#52' and p_type not like 'MEDIUM POLISHED%' and p_size in (45, 1, 3, 25, 31, 6, 22, 24) and ps_suppkey not in ( select s_suppkey from supplier where (s_comment like '%Customer%Complaints%') ) group by p_brand, p_type, p_size order by supplier_cnt desc, p_brand, p_type, p_size;
select o_orderpriority, count(*) as order_count from orders where o_orderdate >= date '1995-12-01' and o_orderdate < DATE '1995-12-01' + INTERVAL 13 MONTH and exists ( select * from lineitem where l_orderkey = o_orderkey and l_commitdate < l_receiptdate ) group by o_orderpriority order by o_orderpriority;
select sum(l_extendedprice * (1 - l_discount)) as revenue from lineitem, part where ( p_partkey = l_partkey and p_brand = 'Brand#35' and p_container in ('SM PACK', 'LG BAG', 'WRAP BOX', 'SM CAN', 'LG JAR') and l_quantity >= 10 and l_quantity <= 19 and p_size between 1 and 8 and l_shipmode in ('AIR', 'AIR REG') and l_shipinstruct = 'DELIVER IN PERSON' ) or ( p_partkey = l_partkey and p_brand = 'Brand#24' and p_container in ('JUMBO DRUM', 'WRAP CASE', 'WRAP BAG', 'SM PACK', 'SM BAG') and l_quantity >= 22 and l_quantity <= 31 and p_size between 1 and 6 and l_shipmode in ('AIR', 'AIR REG') and l_shipinstruct = 'DELIVER IN PERSON' ) or ( p_partkey = l_partkey and p_brand = 'Brand#42' and p_container in ('WRAP JAR', 'LG BOX', 'WRAP PKG', 'WRAP CAN', 'JUMBO JAR') and l_quantity >= 34 and l_quantity <= 41 and p_size between 1 and 12 and l_shipmode in ('AIR', 'AIR REG') and l_shipinstruct = 'DELIVER IN PERSON' );
select o_orderpriority, count(*) as order_count from orders where o_orderdate >= date '1995-12-01' and o_orderdate < DATE '1995-12-01' + INTERVAL 14 MONTH and exists ( select * from lineitem where l_orderkey = o_orderkey and l_commitdate < l_receiptdate ) group by o_orderpriority order by o_orderpriority;
select nation, o_year, sum(amount) as sum_profit from ( select n_name as nation, extract(year from o_orderdate) as o_year, l_extendedprice * (1 - l_discount) - ps_supplycost * l_quantity as amount from part, supplier, lineitem, partsupp, orders, nation where s_suppkey = l_suppkey and ps_suppkey = l_suppkey and ps_partkey = l_partkey and p_partkey = l_partkey and o_orderkey = l_orderkey and s_nationkey = n_nationkey and p_name like '%pink%' ) as profit group by nation, o_year order by nation, o_year desc;
select sum(l_extendedprice * l_discount) as revenue from lineitem where l_shipdate >= date '1996-11-26' and l_shipdate < DATE '1996-11-26' + INTERVAL 4 YEAR and l_discount between 0.04 - 0.03 and 0.04 + 0.03 and l_quantity < 23;
select sum(l_extendedprice * l_discount) as revenue from lineitem where l_shipdate >= date '1995-05-25' and l_shipdate < DATE '1995-05-25' + INTERVAL 2 YEAR and l_discount between 0.08 - 0.03 and 0.08 + 0.03 and l_quantity < 17;
select 100.00 * sum(case when p_type like 'PROMO%' then l_extendedprice * (1 - l_discount) else 0 end) / sum(l_extendedprice * (1 - l_discount)) as promo_revenue from lineitem, part where l_partkey = p_partkey and l_shipdate >= date '1992-08-30' and l_shipdate < DATE '1992-08-30' + INTERVAL 31 MONTH;
select c_count, count(*) as custdist from ( select c_custkey, count(o_orderkey) as c_count from customer left outer join orders on c_custkey = o_custkey and o_comment not like '%pending%packages%' and o_comment not like '%express%deposits%' group by c_custkey ) as c_orders group by c_count order by custdist desc, c_count desc;
select p_brand, p_type, p_size, count(distinct ps_suppkey) as supplier_cnt from partsupp, part where p_partkey = ps_partkey and p_brand <> 'Brand#52' and p_type not like 'STANDARD POLISHED%' and p_type not like 'MEDIUM POLISHED%' and p_size in (35, 22, 50, 49, 43, 24, 36, 45) and ps_suppkey not in ( select s_suppkey from supplier where (s_comment like '%Customer%Dislikes%' or s_comment like '%Customer%Problems%' or s_comment like '%Customer%Issues%') ) group by p_brand, p_type, p_size order by supplier_cnt desc, p_brand, p_type, p_size;
select p_brand, p_type, p_size, count(distinct ps_suppkey) as supplier_cnt from partsupp, part where p_partkey = ps_partkey and p_brand <> 'Brand#52' and p_type not like 'STANDARD POLISHED%' and p_size in (16, 28, 36, 10, 29, 25, 19, 39) and ps_suppkey not in ( select s_suppkey from supplier where (s_comment like '%Customer%Issues%' or s_comment like '%Customer%Damages%') ) group by p_brand, p_type, p_size order by supplier_cnt desc, p_brand, p_type, p_size;
select s_name, s_address from supplier, nation where s_suppkey in ( select ps_suppkey from partsupp where ps_partkey in ( select p_partkey from part where (p_name like '%yellow%') ) and ps_availqty > ( select 0.5 * sum(l_quantity) from lineitem where l_partkey = ps_partkey and l_suppkey = ps_suppkey and l_shipdate >= date '1994-07-07' and l_shipdate < DATE '1994-07-07' + INTERVAL 3 YEAR ) ) and s_nationkey = n_nationkey and n_name = 'CHINA' order by s_name;
select l_returnflag, l_linestatus, sum(l_quantity) as sum_qty, sum(l_extendedprice) as sum_base_price, sum(l_extendedprice * (1 - l_discount)) as sum_disc_price, sum(l_extendedprice * (1 - l_discount) * (1 + l_tax)) as sum_charge, avg(l_quantity) as avg_qty, avg(l_extendedprice) as avg_price, avg(l_discount) as avg_disc, count(*) as count_order from lineitem where l_shipdate <= DATE '1995-07-30' - INTERVAL 99 DAY group by l_returnflag, l_linestatus order by l_returnflag, l_linestatus;
select l_shipmode, sum(case when o_orderpriority = '1-URGENT' or o_orderpriority = '2-HIGH' then 1 else 0 end) as high_line_count, sum(case when o_orderpriority <> '1-URGENT' and o_orderpriority <> '2-HIGH' then 1 else 0 end) as low_line_count from orders, lineitem where o_orderkey = l_orderkey and l_shipmode in ('RAIL', 'AIR', 'SHIP', 'REG AIR') and l_commitdate < l_receiptdate and l_shipdate < l_commitdate and l_receiptdate >= date '1993-11-12' and l_receiptdate < DATE '1993-11-12' + INTERVAL 2 YEAR group by l_shipmode order by l_shipmode;
select l_shipmode, sum(case when o_orderpriority = '1-URGENT' or o_orderpriority = '2-HIGH' then 1 else 0 end) as high_line_count, sum(case when o_orderpriority <> '1-URGENT' and o_orderpriority <> '2-HIGH' then 1 else 0 end) as low_line_count from orders, lineitem where o_orderkey = l_orderkey and l_shipmode in ('FOB', 'MAIL') and l_commitdate < l_receiptdate and l_shipdate < l_commitdate and l_receiptdate >= date '1996-06-09' and l_receiptdate < DATE '1996-06-09' + INTERVAL 5 YEAR group by l_shipmode order by l_shipmode;
select c_name, c_custkey, o_orderkey, o_orderdate, o_totalprice, sum(l_quantity) from customer, orders, lineitem where o_orderkey in ( select l_orderkey from lineitem group by l_orderkey having sum(l_quantity) > 276 ) and c_custkey = o_custkey and o_orderkey = l_orderkey group by c_name, c_custkey, o_orderkey, o_orderdate, o_totalprice order by o_totalprice desc, o_orderdate LIMIT 100;
select p_brand, p_type, p_size, count(distinct ps_suppkey) as supplier_cnt from partsupp, part where p_partkey = ps_partkey and p_brand <> 'Brand#52' and p_type not like 'LARGE POLISHED%' and p_size in (48, 15, 22, 12, 42, 23, 45, 50) and ps_suppkey not in ( select s_suppkey from supplier where (s_comment like '%Customer%Issues%' or s_comment like '%Customer%Dislikes%' or s_comment like '%Customer%Damages%') ) group by p_brand, p_type, p_size order by supplier_cnt desc, p_brand, p_type, p_size;
select p_brand, p_type, p_size, count(distinct ps_suppkey) as supplier_cnt from partsupp, part where p_partkey = ps_partkey and p_brand <> 'Brand#52' and p_type not like 'ECONOMY ANODIZED%' and p_type not like 'MEDIUM POLISHED%' and p_type not like 'LARGE POLISHED%' and p_size in (30, 35, 31, 7, 45, 26, 32, 48) and ps_suppkey not in ( select s_suppkey from supplier where (s_comment like '%Customer%Issues%') ) group by p_brand, p_type, p_size order by supplier_cnt desc, p_brand, p_type, p_size;
select p_brand, p_type, p_size, count(distinct ps_suppkey) as supplier_cnt from partsupp, part where p_partkey = ps_partkey and p_brand <> 'Brand#52' and p_type not like 'ECONOMY ANODIZED%' and p_type not like 'STANDARD POLISHED%' and p_size in (44, 41, 11, 42, 36, 18, 38, 21) and ps_suppkey not in ( select s_suppkey from supplier where (s_comment like '%Customer%Complaints%' or s_comment like '%Customer%Problems%' or s_comment like '%Customer%Damages%') ) group by p_brand, p_type, p_size order by supplier_cnt desc, p_brand, p_type, p_size;
select nation, o_year, sum(amount) as sum_profit from ( select n_name as nation, extract(year from o_orderdate) as o_year, l_extendedprice * (1 - l_discount) - ps_supplycost * l_quantity as amount from part, supplier, lineitem, partsupp, orders, nation where s_suppkey = l_suppkey and ps_suppkey = l_suppkey and ps_partkey = l_partkey and p_partkey = l_partkey and o_orderkey = l_orderkey and s_nationkey = n_nationkey and p_name like '%yellow%' ) as profit group by nation, o_year order by nation, o_year desc;
select s_acctbal, s_name, n_name, p_partkey, p_mfgr, s_address, s_phone, s_comment from part, supplier, partsupp, nation, region where p_partkey = ps_partkey and s_suppkey = ps_suppkey and p_size = 5 and (p_type like '%BRASS') and s_nationkey = n_nationkey and n_regionkey = r_regionkey and (r_name = 'MIDDLE EAST') and ps_supplycost = ( select min(ps_supplycost) from partsupp, supplier, nation, region where p_partkey = ps_partkey and s_suppkey = ps_suppkey and s_nationkey = n_nationkey and n_regionkey = r_regionkey and (r_name = 'MIDDLE EAST') ) order by s_acctbal desc, n_name, s_name, p_partkey LIMIT 100;
